// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";

contract HandleRegistry is AccessControl {
    error InvalidHandleFormat();
    error HandleTaken();
    error HandleReserved();
    error WalletAlreadyHasHandle();
    error NoHandleHeld();

    event HandleClaimed(address indexed owner, string handle);
    event HandleReleased(address indexed owner, string handle);

    mapping(address wallet => bytes32 handleHash) private _handleOf;
    mapping(bytes32 handleHash => address owner) private _ownerOf;
    mapping(bytes32 handleHash => string handle) private _handleString;
    mapping(bytes32 handleHash => bool reserved) private _reserved;

    constructor(address initialAdmin, bytes32[] memory reservedHandleHashes) {
        _grantRole(DEFAULT_ADMIN_ROLE, initialAdmin);

        uint256 length = reservedHandleHashes.length;
        for (uint256 i = 0; i < length; ++i) {
            _reserved[reservedHandleHashes[i]] = true;
        }
    }

    /**
     * @notice Claims a new handle for the caller.
     * @dev Reverts if the format is invalid, the handle is reserved or already taken,
     * or the caller already has a handle.
     * @param handle The handle string to claim.
     */
    function claimHandle(string calldata handle) external {
        _validateHandle(handle);

        bytes32 handleHash = keccak256(bytes(handle));

        if (_reserved[handleHash]) revert HandleReserved();
        if (_ownerOf[handleHash] != address(0)) revert HandleTaken();
        if (_handleOf[msg.sender] != bytes32(0)) revert WalletAlreadyHasHandle();

        _handleOf[msg.sender] = handleHash;
        _ownerOf[handleHash] = msg.sender;
        _handleString[handleHash] = handle;

        emit HandleClaimed(msg.sender, handle);
    }

    /**
     * @notice Releases the caller's current handle.
     * @dev Reverts if the caller does not currently hold a handle.
     */
    function releaseHandle() external {
        bytes32 handleHash = _handleOf[msg.sender];
        if (handleHash == bytes32(0)) revert NoHandleHeld();

        string memory handle = _handleString[handleHash];

        delete _handleOf[msg.sender];
        delete _ownerOf[handleHash];
        delete _handleString[handleHash];

        emit HandleReleased(msg.sender, handle);
    }

    /**
     * @notice Resolves a handle to its owner wallet.
     * @param handle The handle string to resolve.
     * @return The owner address, or address(0) if unclaimed.
     */
    function resolveHandle(string calldata handle) external view returns (address) {
        return _ownerOf[keccak256(bytes(handle))];
    }

    /**
     * @notice Returns the handle currently held by a wallet.
     * @param wallet The wallet to query.
     * @return The handle string, or an empty string if none.
     */
    function handleOf(address wallet) external view returns (string memory) {
        bytes32 handleHash = _handleOf[wallet];
        if (handleHash == bytes32(0)) {
            return "";
        }

        return _handleString[handleHash];
    }

    /**
     * @notice Returns whether a handle hash is reserved.
     * @param handle The handle string to check.
     * @return True if the handle hash is reserved, false otherwise.
     */
    function isReserved(string calldata handle) public view returns (bool) {
        return _reserved[keccak256(bytes(handle))];
    }

    function _validateHandle(string calldata handle) internal pure {
        bytes calldata value = bytes(handle);
        uint256 length = value.length;

        if (length < 3 || length > 20) revert InvalidHandleFormat();

        bytes1 first = value[0];
        if (first < 0x61 || first > 0x7A) revert InvalidHandleFormat();

        for (uint256 i = 1; i < length; ++i) {
            bytes1 char = value[i];

            bool isLowercaseLetter = char >= 0x61 && char <= 0x7A;
            bool isDigit = char >= 0x30 && char <= 0x39;
            bool isUnderscore = char == 0x5F;

            if (!isLowercaseLetter && !isDigit && !isUnderscore) {
                revert InvalidHandleFormat();
            }
        }
    }
}

contracts/KycRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";

contract KycRegistry is AccessControl {
    struct TierRecord {
        uint8 tier;
        uint64 expiry;
    }

    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");

    mapping(address => TierRecord) private _tiers;

    error InvalidTier(uint8 tier);
    error InvalidExpiry();
    error ZeroAddress();

    event TierSet(address indexed wallet, uint8 tier, uint64 expiry);
    event TierRevoked(address indexed wallet);

    constructor(address initialAdmin) {
        if (initialAdmin == address(0)) revert ZeroAddress();
        _grantRole(DEFAULT_ADMIN_ROLE, initialAdmin);
    }

    /**
     * @notice Sets a tier record for a wallet.
     * @dev Callable only by accounts with VERIFIER_ROLE.
     * @param wallet Wallet address whose tier record is updated.
     * @param tier Tier value to store (0, 1, or 2).
     * @param expiry Expiry timestamp for the tier record.
     */
    function setTier(address wallet, uint8 tier, uint64 expiry) external onlyRole(VERIFIER_ROLE) {
        if (wallet == address(0)) revert ZeroAddress();
        if (tier > 2) revert InvalidTier(tier);
        if (expiry <= block.timestamp) revert InvalidExpiry();

        _tiers[wallet] = TierRecord({tier: tier, expiry: expiry});

        emit TierSet(wallet, tier, expiry);
    }

    /**
     * @notice Revokes a wallet tier record.
     * @dev Callable only by accounts with VERIFIER_ROLE.
     * @param wallet Wallet address whose tier record is revoked.
     */
    function revokeTier(address wallet) external onlyRole(VERIFIER_ROLE) {
        if (wallet == address(0)) revert ZeroAddress();

        _tiers[wallet] = TierRecord({tier: 0, expiry: 0});

        emit TierRevoked(wallet);
    }

    /**
     * @notice Returns the effective tier and stored expiry for a wallet.
     * @dev If the stored expiry is zero, returns (0, 0). If expired, returns (0, stored expiry).
     * @param wallet Wallet address to query.
     * @return tier Effective tier value.
     * @return expiry Stored expiry timestamp.
     */
    function getTier(address wallet) public view returns (uint8 tier, uint64 expiry) {
        TierRecord memory record = _tiers[wallet];

        if (record.expiry == 0) {
            return (0, 0);
        }

        if (block.timestamp >= record.expiry) {
            return (0, record.expiry);
        }

        return (record.tier, record.expiry);
    }

    /**
     * @notice Returns only the effective tier for a wallet.
     * @param wallet Wallet address to query.
     * @return tier Effective tier value (0 when unset or expired).
     */
    function effectiveTier(address wallet) public view returns (uint8 tier) {
        (tier, ) = getTier(wallet);
    }
}

contracts/PayRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {KycRegistry} from "./KycRegistry.sol";
import {HandleRegistry} from "./HandleRegistry.sol";

struct TokenPermissions {
    address token;
    uint256 amount;
}

struct PermitTransferFrom {
    TokenPermissions permitted;
    uint256 nonce;
    uint256 deadline;
}

struct SignatureTransferDetails {
    address to;
    uint256 requestedAmount;
}

interface IPermit2 {
    function permitTransferFrom(
        PermitTransferFrom memory permit,
        SignatureTransferDetails calldata transferDetails,
        address owner,
        bytes calldata signature
    ) external;

    function permitWitnessTransferFrom(
        PermitTransferFrom memory permit,
        SignatureTransferDetails calldata transferDetails,
        address owner,
        bytes32 witness,
        string calldata witnessTypeString,
        bytes calldata signature
    ) external;
}

struct InitialBiller {
    address biller;
    address treasury;
}

contract PayRouter is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    struct TierConfig {
        uint96 perPaymentCap;
        uint96 dailyCap;
    }

    enum OrderStatus {
        Pending,
        Fulfilled,
        Rejected,
        Reclaimed
    }

    struct BillOrder {
        address payer;
        address billerTreasury;
        uint128 amount;
        uint128 feeBps;
        uint64 createdAt;
        OrderStatus status;
    }

    struct PendingChange {
        bytes32 changeId;
        uint256 eta;
        bool executed;
    }

    error HandleNotFound(string handle);
    error InsufficientTierForBillOrder();
    error OrderNotPending();
    error OrderNotExpired();
    error InvalidBiller();
    error InvalidAmount();
    error ZeroAddress();
    error InvalidFeeBps(uint16 bps);
    error InvalidConfig();
    error TimelockNotReady();
    error TimelockAlreadyExecuted();
    error TimelockNotQueued();
    error ExceedsGlobalCap();
    error ExceedsTierPerPaymentCap(uint8 tier);
    error ExceedsTierDailyCap(uint8 tier);

    event Sent(address indexed from, address indexed to, uint256 amount);
    event SentToHandle(address indexed from, address indexed to, string handle, uint256 amount);
    event RequestPaid(address indexed payer, address indexed recipient, bytes32 indexed requestId, uint256 amount);
    event OrderCreated(
        bytes32 indexed orderId,
        address indexed payer,
        address indexed billerId,
        bytes32 accountHash,
        bytes32 ref,
        uint256 amount
    );
    event OrderFulfilled(bytes32 indexed orderId, address indexed billerTreasury, uint256 net, uint256 fee);
    event OrderRejected(bytes32 indexed orderId, address indexed payer, uint256 amount);
    event OrderReclaimed(bytes32 indexed orderId, address indexed payer, uint256 amount);
    event ConfigChangeQueued(bytes32 indexed changeKey, uint256 eta);
    event ConfigChangeExecuted(bytes32 indexed changeKey);
    event BillerAdded(address indexed biller, address indexed treasury);
    event BillerRemoved(address indexed biller);

    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    uint16 public constant MAX_FEE_BPS = 200;
    uint256 private constant TIMELOCK_DELAY = 24 hours;

    bytes32 public constant BILL_ORDER_WITNESS_TYPEHASH =
        keccak256("BillOrderWitness(bytes32 orderId,address billerId,bytes32 accountHash,bytes32 ref)");

    bytes32 private constant CHANGE_FEE_BPS = keccak256("feeBps");
    bytes32 private constant CHANGE_GLOBAL_PER_PAYMENT_CAP = keccak256("globalPerPaymentCap");
    bytes32 private constant CHANGE_MIN_BILL_TIER = keccak256("minBillTier");
    bytes32 private constant CHANGE_ORDER_TIMEOUT_SECONDS = keccak256("orderTimeoutSeconds");
    bytes32 private constant CHANGE_ADD_BILLER = keccak256("addBiller");
    bytes32 private constant CHANGE_REMOVE_BILLER = keccak256("removeBiller");
    bytes32 private constant CHANGE_TIER_CONFIG = keccak256("tierConfig");
    bytes32 private constant CHANGE_FEE_WALLET = keccak256("feeWallet");

    IERC20 public immutable usdc;
    KycRegistry public immutable kycRegistry;
    HandleRegistry public immutable handleRegistry;
    IPermit2 public immutable permit2;

    mapping(uint8 => TierConfig) public tierConfigs;
    uint96 public globalPerPaymentCap;
    uint8 public minBillTier;
    uint32 public orderTimeoutSeconds;
    uint16 public feeBps;
    address public feeWallet;

    mapping(address => bool) public isBiller;
    mapping(address => address) public billerTreasury;
    mapping(address => mapping(uint256 => uint128)) private _dailySpend;
    mapping(bytes32 => BillOrder) public orders;
    mapping(address => uint256) private _orderNonces;

    mapping(bytes32 => bytes) private _pendingChanges;
    mapping(bytes32 => uint256) private _pendingEtas;
    mapping(bytes32 => bool) private _pendingExecuted;

    constructor(
        address usdc_,
        address kycRegistry_,
        address handleRegistry_,
        address permit2_,
        address initialAdmin,
        TierConfig memory tier0Config,
        TierConfig memory tier1Config,
        TierConfig memory tier2Config,
        uint96 initialGlobalPerPaymentCap,
        uint8 minBillTier_,
        uint32 orderTimeoutSeconds_,
        uint16 initialFeeBps,
        InitialBiller[] memory initialBillers
    ) {
        if (
            usdc_ == address(0) ||
            kycRegistry_ == address(0) ||
            handleRegistry_ == address(0) ||
            permit2_ == address(0) ||
            initialAdmin == address(0)
        ) {
            revert ZeroAddress();
        }
        if (initialFeeBps > MAX_FEE_BPS) revert InvalidFeeBps(initialFeeBps);
        if (minBillTier_ > 2 || orderTimeoutSeconds_ == 0) revert InvalidConfig();

        usdc = IERC20(usdc_);
        kycRegistry = KycRegistry(kycRegistry_);
        handleRegistry = HandleRegistry(handleRegistry_);
        permit2 = IPermit2(permit2_);

        _grantRole(DEFAULT_ADMIN_ROLE, initialAdmin);
        _grantRole(PAUSER_ROLE, initialAdmin);

        tierConfigs[0] = tier0Config;
        tierConfigs[1] = tier1Config;
        tierConfigs[2] = tier2Config;

        globalPerPaymentCap = initialGlobalPerPaymentCap;
        minBillTier = minBillTier_;
        orderTimeoutSeconds = orderTimeoutSeconds_;
        feeBps = initialFeeBps;
        feeWallet = initialAdmin;

        for (uint256 i = 0; i < initialBillers.length; i++) {
            address b = initialBillers[i].biller;
            address t = initialBillers[i].treasury;
            if (b == address(0) || t == address(0)) revert ZeroAddress();
            isBiller[b] = true;
            billerTreasury[b] = t;
            emit BillerAdded(b, t);
        }
    }

    /**
     * @notice Sends USDC from caller to a recipient using Permit2 signature transfer.
     * @param permit Permit2 transfer authorization.
     * @param sig Signature for the Permit2 transfer.
     * @param recipient Destination wallet.
     * @param amount Amount of USDC (6 decimals) to send.
     */
    function send(
        PermitTransferFrom calldata permit,
        bytes calldata sig,
        address recipient,
        uint256 amount
    ) external whenNotPaused nonReentrant {
        if (recipient == address(0)) revert ZeroAddress();
        if (amount == 0 || amount != permit.permitted.amount) revert InvalidAmount();
        if (permit.permitted.token != address(usdc)) revert InvalidAmount();

        _checkAndRecordSpend(msg.sender, amount);

        permit2.permitTransferFrom(
            permit,
            SignatureTransferDetails({to: recipient, requestedAmount: amount}),
            msg.sender,
            sig
        );

        emit Sent(msg.sender, recipient, amount);
    }

    /**
     * @notice Sends USDC from caller to the wallet that owns a handle.
     * @param permit Permit2 transfer authorization.
     * @param sig Signature for the Permit2 transfer.
     * @param handle Handle to resolve in the handle registry.
     * @param amount Amount of USDC (6 decimals) to send.
     */
    function sendToHandle(
        PermitTransferFrom calldata permit,
        bytes calldata sig,
        string calldata handle,
        uint256 amount
    ) external whenNotPaused nonReentrant {
        address recipient = handleRegistry.resolveHandle(handle);
        if (recipient == address(0)) revert HandleNotFound(handle);
        if (amount == 0 || amount != permit.permitted.amount) revert InvalidAmount();
        if (permit.permitted.token != address(usdc)) revert InvalidAmount();

        _checkAndRecordSpend(msg.sender, amount);

        permit2.permitTransferFrom(
            permit,
            SignatureTransferDetails({to: recipient, requestedAmount: amount}),
            msg.sender,
            sig
        );

        emit SentToHandle(msg.sender, recipient, handle, amount);
    }

    /**
     * @notice Pays a payment request reference from caller to a recipient.
     * @param permit Permit2 transfer authorization.
     * @param sig Signature for the Permit2 transfer.
     * @param requestId Opaque request identifier for indexing.
     * @param recipient Destination wallet.
     * @param amount Amount of USDC (6 decimals) to send.
     */
    function requestPay(
        PermitTransferFrom calldata permit,
        bytes calldata sig,
        bytes32 requestId,
        address recipient,
        uint256 amount
    ) external whenNotPaused nonReentrant {
        if (recipient == address(0)) revert ZeroAddress();
        if (amount == 0 || amount != permit.permitted.amount) revert InvalidAmount();
        if (permit.permitted.token != address(usdc)) revert InvalidAmount();

        _checkAndRecordSpend(msg.sender, amount);

        permit2.permitTransferFrom(
            permit,
            SignatureTransferDetails({to: recipient, requestedAmount: amount}),
            msg.sender,
            sig
        );

        emit RequestPaid(msg.sender, recipient, requestId, amount);
    }

    /**
     * @notice Creates a bill order and escrows USDC in this contract pending operator action.
     * @param permit Permit2 witness transfer authorization.
     * @param sig Signature for the Permit2 witness transfer.
     * @param billerId Registered biller identifier address.
     * @param accountHash Opaque account reference hash.
     * @param ref Opaque bill reference hash.
     * @param amount Amount of USDC (6 decimals) to escrow.
     * @return orderId Deterministic order identifier.
     */
    function createOrder(
        PermitTransferFrom calldata permit,
        bytes calldata sig,
        address billerId,
        bytes32 accountHash,
        bytes32 ref,
        uint256 amount
    ) external whenNotPaused nonReentrant returns (bytes32 orderId) {
        if (kycRegistry.effectiveTier(msg.sender) < minBillTier) revert InsufficientTierForBillOrder();
        if (!isBiller[billerId]) revert InvalidBiller();
        if (amount == 0 || amount != permit.permitted.amount || amount > type(uint128).max) revert InvalidAmount();
        if (permit.permitted.token != address(usdc)) revert InvalidAmount();

        _checkAndRecordSpend(msg.sender, amount);

        // orderId is deterministic from inputs known before signing: uses per-payer nonce
        // so two payers can submit simultaneously without nonce interference.
        orderId = keccak256(abi.encodePacked(msg.sender, billerId, accountHash, ref, _orderNonces[msg.sender]++));
        bytes32 witness = keccak256(abi.encode(BILL_ORDER_WITNESS_TYPEHASH, orderId, billerId, accountHash, ref));

        permit2.permitWitnessTransferFrom(
            permit,
            SignatureTransferDetails({to: address(this), requestedAmount: amount}),
            msg.sender,
            witness,
            string(abi.encodePacked("BillOrderWitness(bytes32 orderId,address billerId,bytes32 accountHash,bytes32 ref) TokenPermissions(address token,uint256 amount)")),
            sig
        );

        orders[orderId] = BillOrder({
            payer: msg.sender,
            billerTreasury: billerTreasury[billerId],
            amount: uint128(amount),
            feeBps: uint128(feeBps),
            createdAt: uint64(block.timestamp),
            status: OrderStatus.Pending
        });

        emit OrderCreated(orderId, msg.sender, billerId, accountHash, ref, amount);
    }

    /**
     * @notice Releases a pending bill order to the treasury locked at order creation.
     * @param orderId Order identifier.
     */
    function fulfillOrder(bytes32 orderId) external onlyRole(OPERATOR_ROLE) nonReentrant {
        BillOrder storage order = orders[orderId];
        _requirePending(order);

        // Cannot fulfill after the order's own deadline — payer's reclaim window has opened.
        if (block.timestamp >= uint256(order.createdAt) + orderTimeoutSeconds) revert OrderNotPending();

        uint256 fee = (uint256(order.amount) * uint256(order.feeBps)) / 10_000;
        uint256 net = uint256(order.amount) - fee;

        order.status = OrderStatus.Fulfilled;

        usdc.safeTransfer(order.billerTreasury, net);
        if (fee > 0) {
            usdc.safeTransfer(feeWallet, fee);
        }

        emit OrderFulfilled(orderId, order.billerTreasury, net, fee);
    }

    /**
     * @notice Rejects a pending bill order and returns funds to the payer.
     * @param orderId Order identifier.
     */
    function rejectOrder(bytes32 orderId) external onlyRole(OPERATOR_ROLE) nonReentrant {
        BillOrder storage order = orders[orderId];
        _requirePending(order);

        order.status = OrderStatus.Rejected;
        usdc.safeTransfer(order.payer, order.amount);

        emit OrderRejected(orderId, order.payer, order.amount);
    }

    /**
     * @notice Reclaims a pending bill order after timeout and returns funds to the payer.
     * @param orderId Order identifier.
     */
    function reclaimOrder(bytes32 orderId) external nonReentrant {
        BillOrder storage order = orders[orderId];
        _requirePending(order);

        if (block.timestamp < uint256(order.createdAt) + orderTimeoutSeconds) revert OrderNotExpired();

        order.status = OrderStatus.Reclaimed;
        usdc.safeTransfer(order.payer, order.amount);

        emit OrderReclaimed(orderId, order.payer, order.amount);
    }

    /**
     * @notice Queues a timelocked configuration change for execution after 24 hours.
     * @param changeKey Configuration key hash.
     * @param encodedChange ABI-encoded change payload for the key.
     */
    function queueConfigChange(bytes32 changeKey, bytes calldata encodedChange) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (!_isSupportedChangeKey(changeKey) || encodedChange.length == 0) revert InvalidConfig();

        uint256 eta = block.timestamp + TIMELOCK_DELAY;
        _pendingChanges[changeKey] = encodedChange;
        _pendingEtas[changeKey] = eta;
        _pendingExecuted[changeKey] = false;

        emit ConfigChangeQueued(changeKey, eta);
    }

    /**
     * @notice Executes a queued configuration change once the timelock has elapsed.
     * @param changeKey Configuration key hash.
     */
    function executeConfigChange(bytes32 changeKey) external onlyRole(DEFAULT_ADMIN_ROLE) {
        uint256 eta = _pendingEtas[changeKey];
        if (eta == 0) revert TimelockNotQueued();
        if (_pendingExecuted[changeKey]) revert TimelockAlreadyExecuted();
        if (block.timestamp < eta) revert TimelockNotReady();

        _pendingExecuted[changeKey] = true;
        _applyConfigChange(changeKey, _pendingChanges[changeKey]);

        emit ConfigChangeExecuted(changeKey);
    }

    /**
     * @notice Pauses new payment entrypoints.
     * @dev Does not pause rejectOrder, reclaimOrder, or operator fulfill.
     */
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @notice Unpauses new payment entrypoints.
     */
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    /**
     * @notice Returns the order nonce that will be used for the next createOrder call from `payer`.
     * @dev Per-payer nonce ensures two concurrent payers never interfere with each other.
     * @param payer Wallet address.
     * @return nonce Current (pre-increment) nonce for this payer.
     */
    function orderNonceOf(address payer) external view returns (uint256 nonce) {
        nonce = _orderNonces[payer];
    }

    /**
     * @notice Returns an account's recorded spend in a day bucket.
     * @param payer Wallet address.
     * @param dayBucket Bucket index computed as timestamp / 1 days.
     * @return amount Recorded spend for the bucket.
     */
    function dailySpend(address payer, uint256 dayBucket) external view returns (uint128 amount) {
        return _dailySpend[payer][dayBucket];
    }

    /**
     * @notice Returns queued metadata for a config key.
     * @param changeKey Configuration key hash.
     * @return pending Pending-change metadata.
     * @return encodedChange ABI-encoded queued payload.
     */
    function getPendingChange(
        bytes32 changeKey
    ) external view returns (PendingChange memory pending, bytes memory encodedChange) {
        uint256 eta = _pendingEtas[changeKey];
        encodedChange = _pendingChanges[changeKey];

        pending = PendingChange({
            changeId: keccak256(abi.encode(changeKey, encodedChange, eta)),
            eta: eta,
            executed: _pendingExecuted[changeKey]
        });
    }

    function _checkAndRecordSpend(address payer, uint256 amount) internal {
        uint8 tier = kycRegistry.effectiveTier(payer);
        TierConfig memory cfg = tierConfigs[tier];

        if (amount > globalPerPaymentCap) revert ExceedsGlobalCap();
        if (amount > cfg.perPaymentCap) revert ExceedsTierPerPaymentCap(tier);

        uint256 day = block.timestamp / 1 days;
        uint256 updated = uint256(_dailySpend[payer][day]) + amount;

        if (cfg.dailyCap != 0 && updated > cfg.dailyCap) revert ExceedsTierDailyCap(tier);
        if (updated > type(uint128).max) revert InvalidAmount();

        _dailySpend[payer][day] = uint128(updated);
    }

    function _requirePending(BillOrder storage order) internal view {
        if (order.status != OrderStatus.Pending) revert OrderNotPending();
    }

    function _isSupportedChangeKey(bytes32 changeKey) internal pure returns (bool) {
        return
            changeKey == CHANGE_FEE_BPS ||
            changeKey == CHANGE_GLOBAL_PER_PAYMENT_CAP ||
            changeKey == CHANGE_MIN_BILL_TIER ||
            changeKey == CHANGE_ORDER_TIMEOUT_SECONDS ||
            changeKey == CHANGE_ADD_BILLER ||
            changeKey == CHANGE_REMOVE_BILLER ||
            changeKey == CHANGE_TIER_CONFIG ||
            changeKey == CHANGE_FEE_WALLET;
    }

    function _applyConfigChange(bytes32 changeKey, bytes memory encodedChange) internal {
        if (changeKey == CHANGE_FEE_BPS) {
            uint16 newFeeBps = abi.decode(encodedChange, (uint16));
            if (newFeeBps > MAX_FEE_BPS) revert InvalidFeeBps(newFeeBps);
            feeBps = newFeeBps;
            return;
        }

        if (changeKey == CHANGE_GLOBAL_PER_PAYMENT_CAP) {
            uint96 newGlobalPerPaymentCap = abi.decode(encodedChange, (uint96));
            globalPerPaymentCap = newGlobalPerPaymentCap;
            return;
        }

        if (changeKey == CHANGE_MIN_BILL_TIER) {
            uint8 newMinBillTier = abi.decode(encodedChange, (uint8));
            if (newMinBillTier > 2) revert InvalidConfig();
            minBillTier = newMinBillTier;
            return;
        }

        if (changeKey == CHANGE_ORDER_TIMEOUT_SECONDS) {
            uint32 newOrderTimeoutSeconds = abi.decode(encodedChange, (uint32));
            if (newOrderTimeoutSeconds == 0) revert InvalidConfig();
            orderTimeoutSeconds = newOrderTimeoutSeconds;
            return;
        }

        if (changeKey == CHANGE_ADD_BILLER) {
            (address biller, address treasury) = abi.decode(encodedChange, (address, address));
            if (biller == address(0) || treasury == address(0)) revert ZeroAddress();

            isBiller[biller] = true;
            billerTreasury[biller] = treasury;
            emit BillerAdded(biller, treasury);
            return;
        }

        if (changeKey == CHANGE_REMOVE_BILLER) {
            address biller = abi.decode(encodedChange, (address));
            if (!isBiller[biller]) revert InvalidBiller();

            isBiller[biller] = false;
            delete billerTreasury[biller];
            emit BillerRemoved(biller);
            return;
        }

        if (changeKey == CHANGE_TIER_CONFIG) {
            (uint8 tier, TierConfig memory cfg) = abi.decode(encodedChange, (uint8, TierConfig));
            if (tier > 2) revert InvalidConfig();

            tierConfigs[tier] = cfg;
            return;
        }

        if (changeKey == CHANGE_FEE_WALLET) {
            address newFeeWallet = abi.decode(encodedChange, (address));
            if (newFeeWallet == address(0)) revert ZeroAddress();

            feeWallet = newFeeWallet;
            return;
        }

        revert InvalidConfig();
    }
}

contracts/ScheduledPayouts.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

struct TokenPermissions {
    address token;
    uint256 amount;
}

struct PermitTransferFrom {
    TokenPermissions permitted;
    uint256 nonce;
    uint256 deadline;
}

struct SignatureTransferDetails {
    address to;
    uint256 requestedAmount;
}

interface IPermit2 {
    function permitTransferFrom(
        PermitTransferFrom memory permit,
        SignatureTransferDetails calldata transferDetails,
        address owner,
        bytes calldata signature
    ) external;

    function permitWitnessTransferFrom(
        PermitTransferFrom memory permit,
        SignatureTransferDetails calldata transferDetails,
        address owner,
        bytes32 witness,
        string calldata witnessTypeString,
        bytes calldata signature
    ) external;
}

contract ScheduledPayouts is AccessControl, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    enum ScheduleType {
        PayLater,
        Allowance,
        Vesting,
        Payroll,
        Streaming
    }

    struct Schedule {
        address sender;
        address recipient;
        ScheduleType scheduleType;
        bool revocable;
        bool cancelled;
        uint128 totalAmount;
        uint128 claimed;
        uint64 startTime;
        uint64 endTime;
        uint64 cliffEnd;
        uint64 period;
        uint128 periodAmount;
    }

    struct ScheduleParams {
        address recipient;
        ScheduleType scheduleType;
        bool revocable;
        uint128 totalAmount;
        uint64 startTime;
        uint64 endTime;
        uint64 cliffEnd;
        uint64 period;
        uint128 periodAmount;
    }

    error ZeroAddress();
    error ZeroAmount();
    error InvalidScheduleParams();
    error ScheduleNotFound();
    error ScheduleCancelled();
    error NotRevocable();
    error NotSender();
    error NothingToClaim();

    event ScheduleCreated(
        bytes32 indexed scheduleId,
        address indexed sender,
        address indexed recipient,
        ScheduleType scheduleType,
        uint128 totalAmount
    );
    event Claimed(bytes32 indexed scheduleId, address indexed recipient, uint128 amount, uint128 totalClaimed);
    event Cancelled(
        bytes32 indexed scheduleId,
        address indexed sender,
        address indexed recipient,
        uint128 recipientAmount,
        uint128 senderRefund
    );
    event Withdrawn(address indexed recipient, uint128 amount);

    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    bytes32 public constant SCHEDULE_WITNESS_TYPEHASH = keccak256(
        "ScheduleWitness(bytes32 scheduleId,address recipient,uint8 scheduleType,bool revocable,uint64 startTime,uint64 endTime,uint64 cliffEnd,uint64 period,uint128 periodAmount,uint128 totalAmount)"
    );

    IERC20 public immutable usdc;
    IPermit2 public immutable permit2;

    mapping(bytes32 => Schedule) public schedules;
    mapping(address => uint128) public pendingWithdrawals;
    mapping(address => uint256) public depositNonces;

    // Invariant:
    // USDC held by this contract equals the aggregate un-distributed amount across schedules:
    // - for active schedules: totalAmount - claimed
    // - for cancelled schedules: totalAmount - vestedTotal_at_cancellation

    constructor(address usdc_, address permit2_, address initialAdmin) {
        if (usdc_ == address(0) || permit2_ == address(0) || initialAdmin == address(0)) {
            revert ZeroAddress();
        }

        usdc = IERC20(usdc_);
        permit2 = IPermit2(permit2_);

        _grantRole(DEFAULT_ADMIN_ROLE, initialAdmin);
        _grantRole(PAUSER_ROLE, initialAdmin);
    }

    /**
     * @notice Deposits sender USDC into a new schedule using Permit2 witness transfer; anyone can relay, but funds are always pulled from msg.sender and held by this contract.
     * @param permit Permit2 witness transfer authorization.
     * @param sig Signature for the Permit2 witness transfer.
     * @param params Schedule creation parameters bound into the Permit2 witness.
     * @return scheduleId Deterministic schedule identifier.
     */
    function deposit(
        PermitTransferFrom calldata permit,
        bytes calldata sig,
        ScheduleParams calldata params
    ) external whenNotPaused nonReentrant returns (bytes32 scheduleId) {
        if (params.recipient == address(0)) revert ZeroAddress();
        if (params.totalAmount == 0) revert ZeroAmount();
        if (params.totalAmount != permit.permitted.amount) revert InvalidScheduleParams();
        if (permit.permitted.token != address(usdc)) revert InvalidScheduleParams();

        if (params.scheduleType == ScheduleType.PayLater) {
            if (params.endTime <= block.timestamp) revert InvalidScheduleParams();
        } else if (params.scheduleType == ScheduleType.Allowance || params.scheduleType == ScheduleType.Payroll) {
            if (params.period == 0 || params.periodAmount == 0 || params.periodAmount > params.totalAmount) {
                revert InvalidScheduleParams();
            }
            if (!(params.startTime == 0 || params.startTime < params.endTime)) {
                revert InvalidScheduleParams();
            }
        } else if (params.scheduleType == ScheduleType.Vesting) {
            if (params.startTime >= params.endTime) revert InvalidScheduleParams();
            if (params.cliffEnd < params.startTime || params.cliffEnd > params.endTime) revert InvalidScheduleParams();
        } else if (params.scheduleType == ScheduleType.Streaming) {
            if (params.startTime >= params.endTime) revert InvalidScheduleParams();
        } else {
            revert InvalidScheduleParams();
        }

        uint256 nonce = depositNonces[msg.sender]++;
        scheduleId = keccak256(abi.encodePacked(msg.sender, params.recipient, nonce));

        bytes32 witness = keccak256(
            abi.encode(
                SCHEDULE_WITNESS_TYPEHASH,
                scheduleId,
                params.recipient,
                uint8(params.scheduleType),
                params.revocable,
                params.startTime,
                params.endTime,
                params.cliffEnd,
                params.period,
                params.periodAmount,
                params.totalAmount
            )
        );

        permit2.permitWitnessTransferFrom(
            permit,
            SignatureTransferDetails({to: address(this), requestedAmount: params.totalAmount}),
            msg.sender,
            witness,
            string(abi.encodePacked("ScheduleWitness(bytes32 scheduleId,address recipient,uint8 scheduleType,bool revocable,uint64 startTime,uint64 endTime,uint64 cliffEnd,uint64 period,uint128 periodAmount,uint128 totalAmount) TokenPermissions(address token,uint256 amount)")),
            sig
        );

        schedules[scheduleId] = Schedule({
            sender: msg.sender,
            recipient: params.recipient,
            scheduleType: params.scheduleType,
            revocable: params.revocable,
            cancelled: false,
            totalAmount: params.totalAmount,
            claimed: 0,
            startTime: params.startTime,
            endTime: params.endTime,
            cliffEnd: params.cliffEnd,
            period: params.period,
            periodAmount: params.periodAmount
        });

        emit ScheduleCreated(scheduleId, msg.sender, params.recipient, params.scheduleType, params.totalAmount);
    }

    /**
     * @notice Claims currently unlocked USDC for a schedule; anyone may call, but the transfer always goes to the schedule recipient.
     * @param scheduleId Schedule identifier.
     */
    function claim(bytes32 scheduleId) external nonReentrant {
        Schedule storage schedule = _getSchedule(scheduleId);
        if (schedule.cancelled) revert ScheduleCancelled();

        uint128 amount = claimableNow(scheduleId);
        if (amount == 0) revert NothingToClaim();

        schedule.claimed += amount;
        _push(schedule.recipient, amount);

        emit Claimed(scheduleId, schedule.recipient, amount, schedule.claimed);
    }

    /**
     * @notice Cancels a revocable schedule; only the original sender can call, unlocked unclaimed USDC goes to recipient and remaining locked USDC is refunded to sender.
     * @param scheduleId Schedule identifier.
     */
    function cancel(bytes32 scheduleId) external nonReentrant {
        Schedule storage schedule = _getSchedule(scheduleId);

        if (!schedule.revocable) revert NotRevocable();
        if (msg.sender != schedule.sender) revert NotSender();
        if (schedule.cancelled) revert ScheduleCancelled();

        uint128 unlockedUnclaimed = claimableNow(scheduleId);
        uint256 vestedTotal = uint256(unlockedUnclaimed) + schedule.claimed;
        uint128 remainder = uint128(uint256(schedule.totalAmount) - vestedTotal);

        schedule.cancelled = true;
        schedule.claimed = uint128(vestedTotal);

        if (unlockedUnclaimed > 0) {
            _push(schedule.recipient, unlockedUnclaimed);
        }
        if (remainder > 0) {
            _push(schedule.sender, remainder);
        }

        emit Cancelled(scheduleId, schedule.sender, schedule.recipient, unlockedUnclaimed, remainder);
    }

    /**
     * @notice Withdraws any USDC credited to the caller from claim or cancel payouts.
     * @dev Exists to allow recovery when a direct safeTransfer would revert (e.g. USDC blocklist).
     *      The contract first attempts a direct transfer in claim/cancel; only if the address has
     *      a pending balance from a prior failed direct transfer can they call withdraw().
     *      In normal operation this function is unused.
     */
    function withdraw() external nonReentrant {
        uint128 amount = pendingWithdrawals[msg.sender];
        if (amount == 0) revert NothingToClaim();
        pendingWithdrawals[msg.sender] = 0;
        usdc.safeTransfer(msg.sender, amount);
        emit Withdrawn(msg.sender, amount);
    }

    /**
     * @notice Returns newly claimable USDC for a schedule at the current timestamp; returns zero for cancelled schedules.
     * @param scheduleId Schedule identifier.
     * @return amount Newly claimable amount not yet claimed.
     */
    function claimableNow(bytes32 scheduleId) public view returns (uint128 amount) {
        Schedule storage schedule = _getSchedule(scheduleId);
        if (schedule.cancelled) return 0;

        uint128 unlocked = _totalUnlocked(schedule);
        if (unlocked <= schedule.claimed) return 0;

        return unlocked - schedule.claimed;
    }

    /// @notice Returns the deposit nonce that will be used for the next deposit from `sender`.
    function nextDepositNonce(address sender) external view returns (uint256) {
        return depositNonces[sender];
    }

    /**
     * @notice Pauses new schedule deposits.
     */
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @notice Unpauses schedule deposits.
     */
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    function _getSchedule(bytes32 scheduleId) internal view returns (Schedule storage schedule) {
        schedule = schedules[scheduleId];
        if (schedule.sender == address(0)) revert ScheduleNotFound();
    }

    function _push(address to, uint128 amount) internal {
        if (amount == 0) return;
        (bool ok, bytes memory data) = address(usdc).call(abi.encodeWithSelector(IERC20.transfer.selector, to, amount));
        bool success = ok && (data.length == 0 || abi.decode(data, (bool)));
        if (!success) {
            pendingWithdrawals[to] += amount;
        }
    }

    function _totalUnlocked(Schedule storage schedule) internal view returns (uint128) {
        if (schedule.scheduleType == ScheduleType.PayLater) {
            return block.timestamp >= schedule.endTime ? schedule.totalAmount : 0;
        }

        if (schedule.scheduleType == ScheduleType.Allowance || schedule.scheduleType == ScheduleType.Payroll) {
            uint256 elapsed = block.timestamp >= schedule.startTime ? block.timestamp - schedule.startTime : 0;
            uint256 periods = elapsed / schedule.period;
            uint256 raw = periods * uint256(schedule.periodAmount);
            if (raw >= schedule.totalAmount) return schedule.totalAmount;
            return uint128(raw);
        }

        if (schedule.scheduleType == ScheduleType.Vesting) {
            if (block.timestamp < schedule.cliffEnd) return 0;

            uint256 t = block.timestamp < schedule.endTime ? block.timestamp : schedule.endTime;
            uint256 window = schedule.endTime - schedule.startTime;
            if (window == 0) return schedule.totalAmount;

            uint256 unlocked = (uint256(schedule.totalAmount) * (t - schedule.startTime)) / window;
            return uint128(unlocked);
        }

        if (schedule.scheduleType == ScheduleType.Streaming) {
            if (block.timestamp <= schedule.startTime) return 0;

            uint256 t = block.timestamp < schedule.endTime ? block.timestamp : schedule.endTime;
            uint256 window = schedule.endTime - schedule.startTime;
            uint256 unlocked = (uint256(schedule.totalAmount) * (t - schedule.startTime)) / window;
            return uint128(unlocked);
        }

        return 0;
    }
}

contracts/script/Create2Factory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Create2} from "@openzeppelin/contracts/utils/Create2.sol";

/// @notice Minimal, reusable CREATE2 factory. Deploys arbitrary bytecode at a
/// deterministic address derived from `msg.sender` (this contract) + salt + bytecode.
/// Not tied to any specific target contract.
contract Create2Factory {
    event Deployed(address indexed deployedAddress, bytes32 indexed salt);

    /// @notice Deploys `bytecode` via CREATE2 at the address determined by `salt`.
    /// @dev Payable so the deployed contract's constructor can receive an initial ETH balance.
    function deploy(bytes32 salt, bytes memory bytecode) external payable returns (address deployedAddress) {
        deployedAddress = Create2.deploy(msg.value, salt, bytecode);
        emit Deployed(deployedAddress, salt);
    }

    /// @notice Predicts the address `deploy` would produce for a given salt + bytecode hash.
    function computeAddress(bytes32 salt, bytes32 bytecodeHash) external view returns (address) {
        return Create2.computeAddress(salt, bytecodeHash);
    }
}

contracts/script/Deploy.s.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Script, console2} from "forge-std/Script.sol";
import {HandleRegistry} from "../HandleRegistry.sol";
import {KycRegistry}    from "../KycRegistry.sol";
import {PayRouter, InitialBiller} from "../PayRouter.sol";
import {ScheduledPayouts} from "../ScheduledPayouts.sol";

/**
 * @title Deploy
 * @notice Deploys all four Dash contracts in dependency order:
 *         HandleRegistry → KycRegistry → PayRouter → ScheduledPayouts
 *
 * Usage (dry-run, no broadcast):
 *   forge script contracts/script/Deploy.s.sol --rpc-url $RPC_URL
 *
 * Usage (Arc testnet broadcast):
 *   forge script contracts/script/Deploy.s.sol \
 *     --rpc-url https://rpc.testnet.arc.io \
 *     --private-key $PRIVATE_KEY \
 *     --broadcast
 *
 * Usage (Arc mainnet — requires explicit approval, review before running):
 *   forge script contracts/script/Deploy.s.sol \
 *     --rpc-url https://rpc.mainnet.arc.io \
 *     --private-key $PRIVATE_KEY \
 *     --broadcast
 *
 * Required environment variables:
 *   DEPLOY_ADMIN_ADDRESS   - multisig or hardware wallet; receives DEFAULT_ADMIN_ROLE on all contracts
 *   DEPLOY_OPERATOR_ADDRESS - backend hot wallet; receives OPERATOR_ROLE on PayRouter
 *   DEPLOY_VERIFIER_ADDRESS - KYC verifier; receives VERIFIER_ROLE on KycRegistry
 *   DEPLOY_PAUSER_ADDRESS  - receives PAUSER_ROLE on PayRouter and ScheduledPayouts
 *
 * Optional (defaults used if absent):
 *   DEPLOY_USDC_ADDRESS    - USDC ERC-20 (default: Arc canonical 0x3600...0000)
 *   DEPLOY_PERMIT2_ADDRESS - Permit2 (default: canonical 0x000000000022D473030F116dDEE9F6B43aC78BA3)
 *   DEPLOY_FEE_WALLET_ADDRESS - fee wallet (default: DEPLOY_ADMIN_ADDRESS)
 *   DEPLOY_BILLER_ADDRESS  - initial biller (default: DEPLOY_OPERATOR_ADDRESS)
 *   DEPLOY_BILLER_TREASURY - initial biller treasury (default: DEPLOY_ADMIN_ADDRESS)
 *
 * After deployment, paste the printed VITE_* lines into .env and restart the dev server.
 */
contract Deploy is Script {
    // ── Arc canonical addresses ───────────────────────────────────
    address internal constant ARC_USDC    = 0x3600000000000000000000000000000000000000;
    address internal constant CANONICAL_PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    // ── Tier limits (6-decimal USDC) ──────────────────────────────
    uint96 internal constant T0_PER_PAYMENT = 5_000_000;           // 5 USDC
    uint96 internal constant T0_DAILY       = 50_000_000;          // 50 USDC
    uint96 internal constant T1_PER_PAYMENT = 100_000_000;         // 100 USDC
    uint96 internal constant T1_DAILY       = 20_000_000_000_000;  // effectively unlimited
    uint96 internal constant T2_PER_PAYMENT = 20_000_000_000_000;  // effectively unlimited
    uint96 internal constant T2_DAILY       = 0;                   // unlimited (0 = no cap)
    uint96 internal constant GLOBAL_CAP     = 25_000_000;          // 25 USDC global ceiling
    uint8  internal constant MIN_BILL_TIER  = 1;
    uint32 internal constant ORDER_TIMEOUT  = 1800;                 // 30 minutes
    uint16 internal constant INITIAL_FEE_BPS = 0;                  // 0% fee at launch

    function run() external {
        // ── Read required env vars ────────────────────────────────
        address admin    = vm.envAddress("DEPLOY_ADMIN_ADDRESS");
        address operator = vm.envAddress("DEPLOY_OPERATOR_ADDRESS");
        address verifier = vm.envAddress("DEPLOY_VERIFIER_ADDRESS");
        address pauser   = vm.envAddress("DEPLOY_PAUSER_ADDRESS");

        // ── Optional env vars with sensible defaults ──────────────
        address usdcAddr    = vm.envOr("DEPLOY_USDC_ADDRESS",    ARC_USDC);
        address permit2Addr = vm.envOr("DEPLOY_PERMIT2_ADDRESS", CANONICAL_PERMIT2);
        address feeWallet   = vm.envOr("DEPLOY_FEE_WALLET_ADDRESS", admin);
        address billerAddr  = vm.envOr("DEPLOY_BILLER_ADDRESS",  operator);
        address billerTreasury = vm.envOr("DEPLOY_BILLER_TREASURY", admin);

        require(admin    != address(0), "DEPLOY_ADMIN_ADDRESS not set");
        require(operator != address(0), "DEPLOY_OPERATOR_ADDRESS not set");
        require(verifier != address(0), "DEPLOY_VERIFIER_ADDRESS not set");
        require(pauser   != address(0), "DEPLOY_PAUSER_ADDRESS not set");

        console2.log("=== Dash deploy ===");
        console2.log("Admin:    ", admin);
        console2.log("Operator: ", operator);
        console2.log("Verifier: ", verifier);
        console2.log("Pauser:   ", pauser);
        console2.log("USDC:     ", usdcAddr);
        console2.log("Permit2:  ", permit2Addr);

        vm.startBroadcast();

        // ── 1. HandleRegistry ─────────────────────────────────────
        bytes32[] memory reserved = new bytes32[](3);
        reserved[0] = keccak256(bytes("dash"));
        reserved[1] = keccak256(bytes("admin"));
        reserved[2] = keccak256(bytes("support"));

        HandleRegistry handleReg = new HandleRegistry(admin, reserved);
        console2.log("HandleRegistry:", address(handleReg));

        // ── 2. KycRegistry ────────────────────────────────────────
        KycRegistry kycReg = new KycRegistry(admin);

        // Grant VERIFIER_ROLE to the verifier wallet
        bytes32 verifierRole = kycReg.VERIFIER_ROLE();
        kycReg.grantRole(verifierRole, verifier);
        console2.log("KycRegistry:   ", address(kycReg));

        // ── 3. PayRouter ──────────────────────────────────────────
        InitialBiller[] memory initialBillers = new InitialBiller[](1);
        initialBillers[0] = InitialBiller({biller: billerAddr, treasury: billerTreasury});

        PayRouter router = new PayRouter(
            usdcAddr,
            address(kycReg),
            address(handleReg),
            permit2Addr,
            admin,
            PayRouter.TierConfig({perPaymentCap: T0_PER_PAYMENT, dailyCap: T0_DAILY}),
            PayRouter.TierConfig({perPaymentCap: T1_PER_PAYMENT, dailyCap: T1_DAILY}),
            PayRouter.TierConfig({perPaymentCap: T2_PER_PAYMENT, dailyCap: T2_DAILY}),
            GLOBAL_CAP,
            MIN_BILL_TIER,
            ORDER_TIMEOUT,
            INITIAL_FEE_BPS,
            initialBillers
        );

        // Grant OPERATOR_ROLE and PAUSER_ROLE
        bytes32 operatorRole = router.OPERATOR_ROLE();
        bytes32 pauserRole   = router.PAUSER_ROLE();
        router.grantRole(operatorRole, operator);
        router.grantRole(pauserRole,   pauser);

        // Transfer feeWallet if different from admin
        // (feeWallet is set to initialAdmin in constructor; queue a change via timelock if needed)
        // Note: feeWallet can only be changed via timelocked queueConfigChange after deploy.

        console2.log("PayRouter:     ", address(router));

        // ── 4. ScheduledPayouts ───────────────────────────────────
        ScheduledPayouts sp = new ScheduledPayouts(usdcAddr, permit2Addr, admin);

        // Grant PAUSER_ROLE on ScheduledPayouts
        bytes32 spPauserRole = sp.PAUSER_ROLE();
        sp.grantRole(spPauserRole, pauser);

        console2.log("ScheduledPayouts:", address(sp));

        vm.stopBroadcast();

        // ── Print .env lines ──────────────────────────────────────
        console2.log("");
        console2.log("=== Add these to .env and restart the dev server ===");
        console2.log(string(abi.encodePacked("VITE_HANDLE_REGISTRY_ADDRESS=",  _toHex(address(handleReg)))));
        console2.log(string(abi.encodePacked("VITE_KYC_REGISTRY_ADDRESS=",     _toHex(address(kycReg)))));
        console2.log(string(abi.encodePacked("VITE_PAY_ROUTER_ADDRESS=",       _toHex(address(router)))));
        console2.log(string(abi.encodePacked("VITE_SCHEDULED_PAYOUTS_ADDRESS=",_toHex(address(sp)))));
        console2.log(string(abi.encodePacked("VITE_FEE_WALLET_ADDRESS=",       _toHex(feeWallet))));
    }

    /// @dev Convert address to "0x..." hex string for console output.
    function _toHex(address addr) internal pure returns (string memory) {
        bytes memory b = abi.encodePacked(addr);
        bytes memory hex_ = new bytes(42);
        hex_[0] = '0'; hex_[1] = 'x';
        bytes memory _hexChars = "0123456789abcdef";
        for (uint256 i = 0; i < 20; i++) {
            hex_[2 + i * 2]     = _hexChars[uint8(b[i]) >> 4];
            hex_[2 + i * 2 + 1] = _hexChars[uint8(b[i]) & 0x0f];
        }
        return string(hex_);
    }
}

contracts/script/DeployCreate2.s.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Script} from "forge-std/Script.sol";
import {Create2Factory} from "./Create2Factory.sol";

/// @notice Deploys a target contract through `Create2Factory` at a deterministic address,
/// predicting the address BEFORE broadcasting and asserting the actual deployment matches.
///
/// Env vars:
///   FACTORY_ADDRESS    - address of an already-deployed Create2Factory (deploy it first via
///                        Mode 1's `deploy_contract` tool; no new tooling needed for the factory itself)
///   CREATE2_SALT        - bytes32 salt, e.g. `cast keccak "my-app-v1"` or any 0x-prefixed 32-byte value
///   CREATION_CODE       - 0x-prefixed creation bytecode of the target contract, ABI-encoded with
///                         constructor args already appended (i.e. `type(Target).creationCode`
///                         concatenated with `abi.encode(ctorArgs...)` — build this off-chain, e.g.
///                         with `cast abi-encode` + `forge inspect Target bytecode`, or inline it in a
///                         thin wrapper script that constructs `abi.encodePacked(type(Target).creationCode, abi.encode(...))`)
///   DEPLOY_VALUE        - optional wei amount to forward to the target's constructor (default 0)
///
/// `CREATE2_SALT` is read via `vm.envBytes32` directly. If you'd rather derive the salt from a
/// human-readable string, read it with `vm.envString("CREATE2_SALT_STRING")` and hash it yourself
/// (`keccak256(bytes(saltString))`) before use — either approach is fine, this script takes the
/// direct bytes32 env var because it avoids an extra hashing step for callers that already have
/// a well-formed salt.
contract DeployCreate2 is Script {
    function run() external returns (address deployedAddress) {
        address factory = vm.envAddress("FACTORY_ADDRESS");
        bytes32 salt = vm.envBytes32("CREATE2_SALT");
        bytes memory creationCode = vm.envBytes("CREATION_CODE");
        uint256 deployValue = vm.envOr("DEPLOY_VALUE", uint256(0));

        bytes32 bytecodeHash = keccak256(creationCode);
        address predicted = vm.computeCreate2Address(salt, bytecodeHash, factory);

        vm.startBroadcast();
        deployedAddress = Create2Factory(factory).deploy{value: deployValue}(salt, creationCode);
        vm.stopBroadcast();

        require(deployedAddress == predicted, "DeployCreate2: actual address did not match prediction");
    }
}

