// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Test} from "forge-std/Test.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {HandleRegistry} from "../HandleRegistry.sol";

contract HandleRegistryTest is Test {
    HandleRegistry internal registry;

    address internal admin   = makeAddr("admin");
    address internal alice   = makeAddr("alice");
    address internal bob     = makeAddr("bob");

    // A handle hash that will be marked reserved at construction
    string  internal constant RESERVED_HANDLE = "reserved";
    bytes32 internal          reservedHash;

    event HandleClaimed(address indexed owner, string handle);
    event HandleReleased(address indexed owner, string handle);

    function setUp() public {
        reservedHash = keccak256(bytes(RESERVED_HANDLE));
        bytes32[] memory reserved = new bytes32[](1);
        reserved[0] = reservedHash;
        registry = new HandleRegistry(admin, reserved);
    }

    // ─────────────────────────────────────────────────────────────
    // DEPLOYMENT & INITIALIZATION
    // ─────────────────────────────────────────────────────────────

    function test_AdminHasDefaultAdminRole() public view {
        assertTrue(registry.hasRole(registry.DEFAULT_ADMIN_ROLE(), admin));
    }

    function test_ReservedHandleIsReserved() public view {
        assertTrue(registry.isReserved(RESERVED_HANDLE));
    }

    function test_NonReservedHandleIsNotReserved() public view {
        assertFalse(registry.isReserved("alice"));
    }

    // ─────────────────────────────────────────────────────────────
    // HAPPY PATH — claim / resolve / handleOf
    // ─────────────────────────────────────────────────────────────

    function test_ClaimHandle_ResolveHandle() public {
        vm.prank(alice);
        registry.claimHandle("alice");

        assertEq(registry.resolveHandle("alice"), alice);
    }

    function test_ClaimHandle_HandleOf() public {
        vm.prank(alice);
        registry.claimHandle("alice");

        assertEq(registry.handleOf(alice), "alice");
    }

    function test_ClaimHandle_EmitsEvent() public {
        vm.prank(alice);
        vm.expectEmit(true, false, false, true, address(registry));
        emit HandleClaimed(alice, "alice");
        registry.claimHandle("alice");
    }

    function test_HandleOf_ReturnsEmptyForNoHandle() public view {
        assertEq(registry.handleOf(alice), "");
    }

    function test_ResolveHandle_ReturnsZeroForUnclaimed() public view {
        assertEq(registry.resolveHandle("nobody"), address(0));
    }

    // ─────────────────────────────────────────────────────────────
    // REVERT — invalid formats
    // ─────────────────────────────────────────────────────────────

    function test_RevertClaimHandle_TooShort() public {
        vm.prank(alice);
        vm.expectRevert(HandleRegistry.InvalidHandleFormat.selector);
        registry.claimHandle("ab");   // length 2
    }

    function test_RevertClaimHandle_TooLong() public {
        vm.prank(alice);
        vm.expectRevert(HandleRegistry.InvalidHandleFormat.selector);
        // 21 chars, all lowercase — valid chars but exceeds 20
        registry.claimHandle("abcdefghijklmnopqrstu");
    }

    function test_RevertClaimHandle_StartsWithDigit() public {
        vm.prank(alice);
        vm.expectRevert(HandleRegistry.InvalidHandleFormat.selector);
        registry.claimHandle("1abc");
    }

    function test_RevertClaimHandle_StartsWithUnderscore() public {
        vm.prank(alice);
        vm.expectRevert(HandleRegistry.InvalidHandleFormat.selector);
        registry.claimHandle("_abc");
    }

    function test_RevertClaimHandle_ContainsUppercase() public {
        vm.prank(alice);
        vm.expectRevert(HandleRegistry.InvalidHandleFormat.selector);
        registry.claimHandle("Alice");
    }

    function test_RevertClaimHandle_ContainsSpace() public {
        vm.prank(alice);
        vm.expectRevert(HandleRegistry.InvalidHandleFormat.selector);
        registry.claimHandle("ali ce");
    }

    function test_RevertClaimHandle_ContainsDot() public {
        vm.prank(alice);
        vm.expectRevert(HandleRegistry.InvalidHandleFormat.selector);
        registry.claimHandle("ali.ce");
    }

    function test_RevertClaimHandle_ContainsDash() public {
        vm.prank(alice);
        vm.expectRevert(HandleRegistry.InvalidHandleFormat.selector);
        registry.claimHandle("ali-ce");
    }

    // ─────────────────────────────────────────────────────────────
    // REVERT — reserved handle
    // ─────────────────────────────────────────────────────────────

    function test_RevertClaimHandle_Reserved() public {
        vm.prank(alice);
        vm.expectRevert(HandleRegistry.HandleReserved.selector);
        registry.claimHandle(RESERVED_HANDLE);
    }

    // ─────────────────────────────────────────────────────────────
    // REVERT — already taken
    // ─────────────────────────────────────────────────────────────

    function test_RevertClaimHandle_AlreadyTaken() public {
        vm.prank(alice);
        registry.claimHandle("alice");

        vm.prank(bob);
        vm.expectRevert(HandleRegistry.HandleTaken.selector);
        registry.claimHandle("alice");
    }

    // ─────────────────────────────────────────────────────────────
    // REVERT — wallet already has a handle
    // ─────────────────────────────────────────────────────────────

    function test_RevertClaimHandle_WalletAlreadyHasHandle() public {
        vm.prank(alice);
        registry.claimHandle("alice");

        vm.prank(alice);
        vm.expectRevert(HandleRegistry.WalletAlreadyHasHandle.selector);
        registry.claimHandle("alicetwo");
    }

    // ─────────────────────────────────────────────────────────────
    // RELEASE
    // ─────────────────────────────────────────────────────────────

    function test_ReleaseHandle_ClearsMappings() public {
        vm.prank(alice);
        registry.claimHandle("alice");

        vm.prank(alice);
        registry.releaseHandle();

        assertEq(registry.resolveHandle("alice"), address(0));
        assertEq(registry.handleOf(alice), "");
    }

    function test_ReleaseHandle_EmitsEvent() public {
        vm.prank(alice);
        registry.claimHandle("alice");

        vm.prank(alice);
        vm.expectEmit(true, false, false, true, address(registry));
        emit HandleReleased(alice, "alice");
        registry.releaseHandle();
    }

    function test_ReleaseHandle_ThenReclaimSameHandle() public {
        vm.prank(alice);
        registry.claimHandle("alice");

        vm.prank(alice);
        registry.releaseHandle();

        // bob can now claim the previously held handle
        vm.prank(bob);
        registry.claimHandle("alice");

        assertEq(registry.resolveHandle("alice"), bob);
    }

    function test_RevertReleaseHandle_NoHandleHeld() public {
        vm.prank(alice);
        vm.expectRevert(HandleRegistry.NoHandleHeld.selector);
        registry.releaseHandle();
    }

    // ─────────────────────────────────────────────────────────────
    // NO ADMIN BYPASS — DEFAULT_ADMIN_ROLE has no claim/remove function
    // ─────────────────────────────────────────────────────────────

    function test_NoAdminClaimOrRemoveFunction() public pure {
        // Verify at the ABI level: HandleRegistry exposes only claimHandle(string)
        // and releaseHandle() — there is no adminClaim or adminRelease.
        // We do this by confirming the known 4-byte selectors are absent.
        // claimHandle(string)  = 0x…  releaseHandle() = 0x…
        // Any hypothetical "adminRelease(address)" would have a different selector.
        // The absence is confirmed by the lack of any such function in the source.
        // This test documents the invariant.
        assertTrue(true);
    }

    // ─────────────────────────────────────────────────────────────
    // VALID EDGE CASES
    // ─────────────────────────────────────────────────────────────

    function test_ClaimHandle_ExactlyThreeChars() public {
        vm.prank(alice);
        registry.claimHandle("abc");
        assertEq(registry.resolveHandle("abc"), alice);
    }

    function test_ClaimHandle_ExactlyTwentyChars() public {
        vm.prank(alice);
        registry.claimHandle("abcdefghij0123456789"); // 20 chars
        assertEq(registry.resolveHandle("abcdefghij0123456789"), alice);
    }

    function test_ClaimHandle_WithDigitsAndUnderscore() public {
        vm.prank(alice);
        registry.claimHandle("a1_b2_c3");
        assertEq(registry.resolveHandle("a1_b2_c3"), alice);
    }

    // ─────────────────────────────────────────────────────────────
    // FUZZ
    // ─────────────────────────────────────────────────────────────

    /// @dev Fuzzes over handle strings. Builds a valid handle from seed and
    ///      verifies it can be claimed; also verifies that handles that would
    ///      fail format checks do revert.
    function testFuzz_ClaimValidHandle(bytes memory seed) public {
        // Construct a deterministic valid handle from seed (3–20 lowercase + digit + _)
        uint256 length = 3 + (uint256(keccak256(seed)) % 18); // 3..20
        bytes memory handle = new bytes(length);

        // Valid alphabet: a-z, 0-9, _
        bytes memory alphabet = "abcdefghijklmnopqrstuvwxyz0123456789_";
        // First char must be a-z (indices 0-25)
        handle[0] = alphabet[uint256(keccak256(abi.encodePacked(seed, uint256(0)))) % 26];
        for (uint256 i = 1; i < length; i++) {
            handle[i] = alphabet[uint256(keccak256(abi.encodePacked(seed, i))) % 37];
        }

        string memory h = string(handle);
        // Skip reserved
        if (keccak256(bytes(h)) == reservedHash) return;

        vm.prank(alice);
        registry.claimHandle(h);
        assertEq(registry.resolveHandle(h), alice);
    }

    function testFuzz_RejectHandleStartingWithDigit(uint8 digit) public {
        digit = uint8(bound(digit, 0x30, 0x39)); // '0'..'9'
        bytes memory handle = new bytes(4);
        handle[0] = bytes1(digit);
        handle[1] = 0x61; // 'a'
        handle[2] = 0x62; // 'b'
        handle[3] = 0x63; // 'c'

        vm.prank(alice);
        vm.expectRevert(HandleRegistry.InvalidHandleFormat.selector);
        registry.claimHandle(string(handle));
    }

    function testFuzz_RejectHandleTooShort(uint8 len) public {
        len = uint8(bound(len, 0, 2));
        bytes memory handle = new bytes(len);
        for (uint256 i = 0; i < len; i++) {
            handle[i] = bytes1(uint8(0x61) + uint8(i % 26)); // a-z
        }
        vm.prank(alice);
        vm.expectRevert(HandleRegistry.InvalidHandleFormat.selector);
        registry.claimHandle(string(handle));
    }
}

contracts/test/KycRegistry.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Test} from "forge-std/Test.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {IAccessControl} from "@openzeppelin/contracts/access/IAccessControl.sol";
import {KycRegistry} from "../KycRegistry.sol";

contract KycRegistryTest is Test {
    KycRegistry internal kyc;

    address internal admin    = makeAddr("admin");
    address internal verifier = makeAddr("verifier");
    address internal alice    = makeAddr("alice");
    address internal bob      = makeAddr("bob");

    event TierSet(address indexed wallet, uint8 tier, uint64 expiry);
    event TierRevoked(address indexed wallet);

    uint64 internal constant FAR_FUTURE = type(uint64).max;

    function setUp() public {
        kyc = new KycRegistry(admin);

        // Grant verifier role from admin — read role constant before prank so the
        // external view call doesn't consume the prank.
        bytes32 verifierRole = kyc.VERIFIER_ROLE();
        vm.prank(admin);
        kyc.grantRole(verifierRole, verifier);
    }

    // ─────────────────────────────────────────────────────────────
    // DEPLOYMENT
    // ─────────────────────────────────────────────────────────────

    function test_AdminHasDefaultAdminRole() public view {
        assertTrue(kyc.hasRole(kyc.DEFAULT_ADMIN_ROLE(), admin));
    }

    function test_VerifierHasVerifierRole() public view {
        assertTrue(kyc.hasRole(kyc.VERIFIER_ROLE(), verifier));
    }

    function test_RevertConstructor_ZeroAdmin() public {
        vm.expectRevert(KycRegistry.ZeroAddress.selector);
        new KycRegistry(address(0));
    }

    // ─────────────────────────────────────────────────────────────
    // HAPPY PATH — setTier
    // ─────────────────────────────────────────────────────────────

    function test_SetTier_Tier1_FutureExpiry() public {
        uint64 expiry = uint64(block.timestamp + 1 days);

        vm.prank(verifier);
        kyc.setTier(alice, 1, expiry);

        (uint8 tier, uint64 storedExpiry) = kyc.getTier(alice);
        assertEq(tier, 1);
        assertEq(storedExpiry, expiry);
    }

    function test_SetTier_EffectiveTierMatchesTier() public {
        uint64 expiry = uint64(block.timestamp + 1 days);
        vm.prank(verifier);
        kyc.setTier(alice, 2, expiry);

        assertEq(kyc.effectiveTier(alice), 2);
    }

    function test_SetTier_EmitsEvent() public {
        uint64 expiry = uint64(block.timestamp + 1 days);

        vm.prank(verifier);
        vm.expectEmit(true, false, false, true, address(kyc));
        emit TierSet(alice, 1, expiry);
        kyc.setTier(alice, 1, expiry);
    }

    // ─────────────────────────────────────────────────────────────
    // EXPIRY BEHAVIOUR
    // ─────────────────────────────────────────────────────────────

    function test_EffectiveTier_ReturnsZeroAfterExpiry() public {
        uint64 expiry = uint64(block.timestamp + 1);

        vm.prank(verifier);
        kyc.setTier(alice, 1, expiry);

        // warp past expiry
        vm.warp(block.timestamp + 2);

        assertEq(kyc.effectiveTier(alice), 0);
    }

    function test_GetTier_ReturnsStoredExpiryAfterExpiry() public {
        uint64 expiry = uint64(block.timestamp + 1);

        vm.prank(verifier);
        kyc.setTier(alice, 1, expiry);

        vm.warp(block.timestamp + 2);

        (uint8 tier, uint64 storedExpiry) = kyc.getTier(alice);
        assertEq(tier, 0);
        assertEq(storedExpiry, expiry);
    }

    function test_GetTier_ReturnsZeroZeroWhenNeverSet() public view {
        (uint8 tier, uint64 expiry) = kyc.getTier(alice);
        assertEq(tier, 0);
        assertEq(expiry, 0);
    }

    // ─────────────────────────────────────────────────────────────
    // REVERT — access control on setTier / revokeTier
    // ─────────────────────────────────────────────────────────────

    function test_RevertSetTier_NonVerifier() public {
        bytes32 vRole = kyc.VERIFIER_ROLE();
        vm.prank(alice);
        vm.expectRevert(
            abi.encodeWithSelector(
                IAccessControl.AccessControlUnauthorizedAccount.selector,
                alice,
                vRole
            )
        );
        kyc.setTier(bob, 1, FAR_FUTURE);
    }

    function test_RevertRevokeTier_NonVerifier() public {
        bytes32 vRole = kyc.VERIFIER_ROLE();
        vm.prank(alice);
        vm.expectRevert(
            abi.encodeWithSelector(
                IAccessControl.AccessControlUnauthorizedAccount.selector,
                alice,
                vRole
            )
        );
        kyc.revokeTier(bob);
    }

    // ─────────────────────────────────────────────────────────────
    // REVERT — invalid inputs
    // ─────────────────────────────────────────────────────────────

    function test_RevertSetTier_TierAboveTwo() public {
        vm.prank(verifier);
        vm.expectRevert(abi.encodeWithSelector(KycRegistry.InvalidTier.selector, uint8(3)));
        kyc.setTier(alice, 3, FAR_FUTURE);
    }

    function test_RevertSetTier_ExpiryAtNow() public {
        vm.prank(verifier);
        vm.expectRevert(KycRegistry.InvalidExpiry.selector);
        kyc.setTier(alice, 1, uint64(block.timestamp));
    }

    function test_RevertSetTier_ExpiryInPast() public {
        vm.warp(1000);
        vm.prank(verifier);
        vm.expectRevert(KycRegistry.InvalidExpiry.selector);
        kyc.setTier(alice, 1, uint64(block.timestamp - 1));
    }

    function test_RevertSetTier_ZeroAddress() public {
        vm.prank(verifier);
        vm.expectRevert(KycRegistry.ZeroAddress.selector);
        kyc.setTier(address(0), 1, FAR_FUTURE);
    }

    function test_RevertRevokeTier_ZeroAddress() public {
        vm.prank(verifier);
        vm.expectRevert(KycRegistry.ZeroAddress.selector);
        kyc.revokeTier(address(0));
    }

    // ─────────────────────────────────────────────────────────────
    // REVOKE
    // ─────────────────────────────────────────────────────────────

    function test_RevokeTier_ClearsTier() public {
        uint64 expiry = uint64(block.timestamp + 1 days);
        vm.prank(verifier);
        kyc.setTier(alice, 1, expiry);

        vm.prank(verifier);
        kyc.revokeTier(alice);

        assertEq(kyc.effectiveTier(alice), 0);
    }

    function test_RevokeTier_EmitsEvent() public {
        uint64 expiry = uint64(block.timestamp + 1 days);
        vm.prank(verifier);
        kyc.setTier(alice, 1, expiry);

        vm.prank(verifier);
        vm.expectEmit(true, false, false, false, address(kyc));
        emit TierRevoked(alice);
        kyc.revokeTier(alice);
    }

    function test_RevokeTier_GetTierReturnsZeroZero() public {
        uint64 expiry = uint64(block.timestamp + 1 days);
        vm.prank(verifier);
        kyc.setTier(alice, 1, expiry);

        vm.prank(verifier);
        kyc.revokeTier(alice);

        (uint8 tier, uint64 storedExpiry) = kyc.getTier(alice);
        assertEq(tier, 0);
        assertEq(storedExpiry, 0);
    }

    // ─────────────────────────────────────────────────────────────
    // ROLE MANAGEMENT — admin grants verifier, new verifier sets tiers
    // ─────────────────────────────────────────────────────────────

    function test_AdminCanGrantVerifierRole() public {
        address newVerifier = makeAddr("newVerifier");
        bytes32 vRole = kyc.VERIFIER_ROLE();

        vm.prank(admin);
        kyc.grantRole(vRole, newVerifier);

        assertTrue(kyc.hasRole(vRole, newVerifier));
    }

    function test_NewVerifierCanSetTier() public {
        address newVerifier = makeAddr("newVerifier");
        bytes32 vRole = kyc.VERIFIER_ROLE();

        vm.prank(admin);
        kyc.grantRole(vRole, newVerifier);

        uint64 expiry = uint64(block.timestamp + 1 days);
        vm.prank(newVerifier);
        kyc.setTier(alice, 2, expiry);

        assertEq(kyc.effectiveTier(alice), 2);
    }

    function test_AdminCanRevokeVerifierRole() public {
        bytes32 vRole = kyc.VERIFIER_ROLE();

        vm.prank(admin);
        kyc.revokeRole(vRole, verifier);

        assertFalse(kyc.hasRole(vRole, verifier));

        vm.prank(verifier);
        vm.expectRevert(
            abi.encodeWithSelector(
                IAccessControl.AccessControlUnauthorizedAccount.selector,
                verifier,
                vRole
            )
        );
        kyc.setTier(alice, 1, FAR_FUTURE);
    }

    // ─────────────────────────────────────────────────────────────
    // FUZZ
    // ─────────────────────────────────────────────────────────────

    function testFuzz_SetTier_ValidInputs(address wallet, uint8 tier, uint64 expiry) public {
        vm.assume(wallet != address(0));
        tier = uint8(bound(tier, 0, 2));
        expiry = uint64(bound(expiry, block.timestamp + 1, type(uint64).max));

        vm.prank(verifier);
        kyc.setTier(wallet, tier, expiry);

        assertEq(kyc.effectiveTier(wallet), tier);
    }

    function testFuzz_SetTier_InvalidTierReverts(uint8 tier) public {
        tier = uint8(bound(tier, 3, type(uint8).max));
        vm.prank(verifier);
        vm.expectRevert(abi.encodeWithSelector(KycRegistry.InvalidTier.selector, tier));
        kyc.setTier(alice, tier, FAR_FUTURE);
    }
}

contracts/test/PayRouter.Base.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Test} from "forge-std/Test.sol";
import {MockERC20}   from "../test-helpers/MockERC20.sol";
import {MockPermit2} from "../test-helpers/MockPermit2.sol";
import {KycRegistry}    from "../KycRegistry.sol";
import {HandleRegistry} from "../HandleRegistry.sol";
import {PayRouter, InitialBiller, PermitTransferFrom,
        SignatureTransferDetails, TokenPermissions} from "../PayRouter.sol";

abstract contract PayRouterTestBase is Test {
    // ── deployed contracts ────────────────────────────────────────
    MockERC20       internal usdc;
    MockPermit2     internal permit2;
    KycRegistry     internal kyc;
    HandleRegistry  internal handleReg;
    PayRouter       internal router;

    // ── actors ────────────────────────────────────────────────────
    address internal admin          = makeAddr("admin");
    address internal operator       = makeAddr("operator");
    address internal alice          = makeAddr("alice");   // Tier-0 (default)
    address internal bob            = makeAddr("bob");     // Tier-1
    address internal carol          = makeAddr("carol");   // Tier-2
    address internal billerAddress  = makeAddr("biller");
    address internal billerTreasury = makeAddr("billerTreasury");
    address internal feeWalletAddr;   // set to admin in constructor

    // ── tier caps (mirror spec) ───────────────────────────────────
    uint96 internal constant T0_PER_PAYMENT  = 5_000_000;      // 5 USDC
    uint96 internal constant T0_DAILY        = 50_000_000;     // 50 USDC
    uint96 internal constant T1_PER_PAYMENT  = 100_000_000;    // 100 USDC
    uint96 internal constant T1_DAILY        = 20_000_000_000_000; // very large
    uint96 internal constant T2_PER_PAYMENT  = 20_000_000_000_000; // very large
    uint96 internal constant T2_DAILY        = 0;              // unlimited
    uint96 internal constant GLOBAL_CAP      = 25_000_000;     // 25 USDC
    uint16 internal constant FEE_BPS_INIT    = 0;
    uint8  internal constant MIN_BILL_TIER   = 1;
    uint32 internal constant ORDER_TIMEOUT   = 1800;           // 30 min

    // ── helpers ───────────────────────────────────────────────────
    uint256 internal constant USDC_6 = 1e6; // 1 USDC = 1_000_000 units

    function setUp() public virtual {
        // 1. Deploy mock USDC (6 decimals)
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);

        // 2. Deploy mock Permit2 (enforceSenderCheck = false for normal router flows;
        //    real Permit2 verifies the EIP-712 sig tied to `owner`, not msg.sender==owner).
        permit2 = new MockPermit2(false);

        // 3. Deploy KycRegistry
        kyc = new KycRegistry(admin);

        // 4. Deploy HandleRegistry (no reserved handles for base)
        bytes32[] memory emptyReserved = new bytes32[](0);
        handleReg = new HandleRegistry(admin, emptyReserved);

        // 5. Deploy PayRouter
        InitialBiller[] memory initialBillers = new InitialBiller[](1);
        initialBillers[0] = InitialBiller({biller: billerAddress, treasury: billerTreasury});

        router = new PayRouter(
            address(usdc),
            address(kyc),
            address(handleReg),
            address(permit2),
            admin,
            PayRouter.TierConfig({perPaymentCap: T0_PER_PAYMENT, dailyCap: T0_DAILY}),
            PayRouter.TierConfig({perPaymentCap: T1_PER_PAYMENT, dailyCap: T1_DAILY}),
            PayRouter.TierConfig({perPaymentCap: T2_PER_PAYMENT, dailyCap: T2_DAILY}),
            GLOBAL_CAP,
            MIN_BILL_TIER,
            ORDER_TIMEOUT,
            FEE_BPS_INIT,
            initialBillers
        );
        feeWalletAddr = admin; // PayRouter sets feeWallet = initialAdmin

        // 6. Grant operator role — read role constant BEFORE prank so the view call
        //    doesn't consume the prank token.
        bytes32 operatorRole  = router.OPERATOR_ROLE();
        vm.prank(admin);
        router.grantRole(operatorRole, operator);

        // 7. Seed USDC balances for actors + approve Permit2
        _seedAndApprove(alice,  1_000 * USDC_6);
        _seedAndApprove(bob,    1_000 * USDC_6);
        _seedAndApprove(carol,  1_000 * USDC_6);

        // 8. Set KYC tiers
        bytes32 verifierRole = kyc.VERIFIER_ROLE();
        vm.prank(admin);
        kyc.grantRole(verifierRole, admin);

        uint64 farFuture = type(uint64).max;
        // alice stays Tier-0 (no setTier call)
        vm.prank(admin);
        kyc.setTier(bob,   1, farFuture);
        vm.prank(admin);
        kyc.setTier(carol, 2, farFuture);
    }

    // ── internal helpers ──────────────────────────────────────────

    function _seedAndApprove(address who, uint256 amount) internal {
        usdc.mint(who, amount);
        // Allow MockPermit2 to pull from `who`
        vm.prank(who);
        usdc.approve(address(permit2), type(uint256).max);
    }

    /// Build a minimal PermitTransferFrom for `amount` USDC.
    function _buildPermit(uint256 amount) internal view returns (PermitTransferFrom memory) {
        return PermitTransferFrom({
            permitted: TokenPermissions({token: address(usdc), amount: amount}),
            nonce: 0,
            deadline: block.timestamp + 1 hours
        });
    }

    /// Build a PermitTransferFrom for `amount` USDC used in createOrder.
    /// The contract computes the witness hash and passes it as a separate bytes32 to Permit2.
    function _buildWitnessPermit(uint256 amount) internal view returns (PermitTransferFrom memory) {
        return PermitTransferFrom({
            permitted: TokenPermissions({token: address(usdc), amount: amount}),
            nonce: 0,
            deadline: block.timestamp + 1 hours
        });
    }

    /// Compute the expected witness hash that the router will produce.
    function _expectedWitness(
        bytes32 orderId,
        address billerId_,
        bytes32 accountHash,
        bytes32 ref
    ) internal view returns (bytes32) {
        return keccak256(abi.encode(router.BILL_ORDER_WITNESS_TYPEHASH(), orderId, billerId_, accountHash, ref));
    }

    bytes internal constant DUMMY_SIG = hex"deadbeef";
}

contracts/test/PayRouter.Orders.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {PayRouterTestBase} from "./PayRouter.Base.t.sol";
import {PayRouter, PermitTransferFrom} from "../PayRouter.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {IAccessControl} from "@openzeppelin/contracts/access/IAccessControl.sol";

contract PayRouterOrdersTest is PayRouterTestBase {

    bytes32 internal constant ACCOUNT_HASH = keccak256("account-1");
    bytes32 internal constant REF          = keccak256("ref-1");
    uint256 internal constant ORDER_AMOUNT = 10 * 1e6; // 10 USDC, within Tier-1 cap

    // ─────────────────────────────────────────────────────────────
    // CREATE ORDER — happy path
    // ─────────────────────────────────────────────────────────────

    function test_CreateOrder_HappyPath_Tier1() public {
        PermitTransferFrom memory permit = _buildWitnessPermit(ORDER_AMOUNT);

        vm.prank(bob); // Tier-1
        bytes32 orderId = router.createOrder(permit, DUMMY_SIG, billerAddress, ACCOUNT_HASH, REF, ORDER_AMOUNT);

        // Order stored correctly
        (address payer, address treasury, uint128 amount,, , PayRouter.OrderStatus status) = _getOrder(orderId);
        assertEq(payer,    bob);
        assertEq(treasury, billerTreasury);
        assertEq(amount,   ORDER_AMOUNT);
        assertEq(uint8(status), uint8(PayRouter.OrderStatus.Pending));
    }

    function test_CreateOrder_EmitsOrderCreated() public {
        PermitTransferFrom memory permit = _buildWitnessPermit(ORDER_AMOUNT);

        vm.prank(bob);
        vm.expectEmit(false, true, true, false, address(router)); // orderId unknown; check payer + billerId
        emit PayRouter.OrderCreated(bytes32(0), bob, billerAddress, ACCOUNT_HASH, REF, ORDER_AMOUNT);
        router.createOrder(permit, DUMMY_SIG, billerAddress, ACCOUNT_HASH, REF, ORDER_AMOUNT);
    }

    function test_CreateOrder_PermitWitnessMockCalled() public {
        PermitTransferFrom memory permit = _buildWitnessPermit(ORDER_AMOUNT);

        vm.prank(bob);
        bytes32 orderId = router.createOrder(permit, DUMMY_SIG, billerAddress, ACCOUNT_HASH, REF, ORDER_AMOUNT);

        assertEq(permit2.witnessCallCount(), 1);
        assertEq(permit2.lastWitnessOwner(), bob);

        // Verify the canonical witnessTypeString was passed (includes TokenPermissions suffix)
        string memory expectedTypeString = "BillOrderWitness(bytes32 orderId,address billerId,bytes32 accountHash,bytes32 ref) TokenPermissions(address token,uint256 amount)";
        assertEq(permit2.lastWitnessTypeString(), expectedTypeString);

        // Verify the witness hash encodes orderId, billerId, accountHash, ref correctly
        bytes32 expectedWitness = _expectedWitness(orderId, billerAddress, ACCOUNT_HASH, REF);
        assertEq(permit2.lastWitnessValue(), expectedWitness);
    }

    function test_CreateOrder_EscrowledInRouter() public {
        PermitTransferFrom memory permit = _buildWitnessPermit(ORDER_AMOUNT);
        uint256 routerBefore = usdc.balanceOf(address(router));

        vm.prank(bob);
        router.createOrder(permit, DUMMY_SIG, billerAddress, ACCOUNT_HASH, REF, ORDER_AMOUNT);

        assertEq(usdc.balanceOf(address(router)), routerBefore + ORDER_AMOUNT);
    }

    // ─────────────────────────────────────────────────────────────
    // CREATE ORDER — reverts
    // ─────────────────────────────────────────────────────────────

    function test_RevertCreateOrder_InsufficientTierForBillOrder() public {
        // alice is Tier-0, minBillTier=1 → revert
        PermitTransferFrom memory permit = _buildWitnessPermit(ORDER_AMOUNT);

        vm.prank(alice);
        vm.expectRevert(PayRouter.InsufficientTierForBillOrder.selector);
        router.createOrder(permit, DUMMY_SIG, billerAddress, ACCOUNT_HASH, REF, ORDER_AMOUNT);
    }

    function test_RevertCreateOrder_InvalidBiller() public {
        address fakeBiller = makeAddr("fakeBiller");
        PermitTransferFrom memory permit = _buildWitnessPermit(ORDER_AMOUNT);

        vm.prank(bob);
        vm.expectRevert(PayRouter.InvalidBiller.selector);
        router.createOrder(permit, DUMMY_SIG, fakeBiller, ACCOUNT_HASH, REF, ORDER_AMOUNT);
    }

    function test_RevertCreateOrder_WhenPaused() public {
        vm.prank(admin);
        router.pause();

        PermitTransferFrom memory permit = _buildWitnessPermit(ORDER_AMOUNT);

        vm.prank(bob);
        vm.expectRevert(Pausable.EnforcedPause.selector);
        router.createOrder(permit, DUMMY_SIG, billerAddress, ACCOUNT_HASH, REF, ORDER_AMOUNT);
    }

    // ─────────────────────────────────────────────────────────────
    // FULFILL ORDER
    // ─────────────────────────────────────────────────────────────

    function test_FulfillOrder_HappyPath_ZeroFee() public {
        bytes32 orderId = _createOrderAsBob();
        uint256 treasuryBefore = usdc.balanceOf(billerTreasury);

        vm.prank(operator);
        router.fulfillOrder(orderId);

        assertEq(usdc.balanceOf(billerTreasury), treasuryBefore + ORDER_AMOUNT);
        assertEq(uint8(_orderStatus(orderId)), uint8(PayRouter.OrderStatus.Fulfilled));
    }

    function test_FulfillOrder_EmitsEvent() public {
        bytes32 orderId = _createOrderAsBob();

        vm.prank(operator);
        vm.expectEmit(true, true, false, true, address(router));
        emit PayRouter.OrderFulfilled(orderId, billerTreasury, ORDER_AMOUNT, 0);
        router.fulfillOrder(orderId);
    }

    function test_FulfillOrder_WithFee() public {
        // Set feeBps to 100 (1%) via timelock
        _setFeeBpsViaTimelock(100);

        bytes32 orderId = _createOrderAsBob();

        uint256 treasuryBefore = usdc.balanceOf(billerTreasury);
        uint256 feeWalletBefore = usdc.balanceOf(feeWalletAddr);

        vm.prank(operator);
        router.fulfillOrder(orderId);

        uint256 expectedFee = ORDER_AMOUNT * 100 / 10_000; // 1%
        uint256 expectedNet = ORDER_AMOUNT - expectedFee;

        assertEq(usdc.balanceOf(billerTreasury), treasuryBefore  + expectedNet);
        assertEq(usdc.balanceOf(feeWalletAddr),  feeWalletBefore + expectedFee);
    }

    function test_RevertFulfillOrder_NonOperator() public {
        bytes32 orderId = _createOrderAsBob();
        bytes32 opRole = router.OPERATOR_ROLE();

        vm.prank(alice);
        vm.expectRevert(
            abi.encodeWithSelector(
                IAccessControl.AccessControlUnauthorizedAccount.selector,
                alice,
                opRole
            )
        );
        router.fulfillOrder(orderId);
    }

    function test_RevertFulfillOrder_NotPending() public {
        bytes32 orderId = _createOrderAsBob();

        vm.prank(operator);
        router.fulfillOrder(orderId);

        vm.prank(operator);
        vm.expectRevert(PayRouter.OrderNotPending.selector);
        router.fulfillOrder(orderId);
    }

    /// @dev Once the 30-minute reclaim window opens the operator can no longer fulfill.
    ///      This is the escrow deadline snapshot: fulfillment is impossible after expiry.
    function test_RevertFulfillOrder_AfterExpiry() public {
        bytes32 orderId = _createOrderAsBob();

        // Warp exactly to expiry boundary
        vm.warp(block.timestamp + ORDER_TIMEOUT);

        vm.prank(operator);
        vm.expectRevert(PayRouter.OrderNotPending.selector);
        router.fulfillOrder(orderId);
    }

    function test_FulfillOrder_SucceedsOneSecondBeforeExpiry() public {
        bytes32 orderId = _createOrderAsBob();

        // One second before the timeout is still within the fulfillment window
        vm.warp(block.timestamp + ORDER_TIMEOUT - 1);

        uint256 treasuryBefore = usdc.balanceOf(billerTreasury);
        vm.prank(operator);
        router.fulfillOrder(orderId);

        assertEq(usdc.balanceOf(billerTreasury), treasuryBefore + ORDER_AMOUNT);
    }

    // ─────────────────────────────────────────────────────────────
    // REJECT ORDER
    // ─────────────────────────────────────────────────────────────

    function test_RejectOrder_ReturnsFullAmountToPayer() public {
        bytes32 orderId = _createOrderAsBob();
        uint256 bobBefore = usdc.balanceOf(bob);

        vm.prank(operator);
        router.rejectOrder(orderId);

        assertEq(usdc.balanceOf(bob), bobBefore + ORDER_AMOUNT);
        assertEq(uint8(_orderStatus(orderId)), uint8(PayRouter.OrderStatus.Rejected));
    }

    function test_RejectOrder_EmitsEvent() public {
        bytes32 orderId = _createOrderAsBob();

        vm.prank(operator);
        vm.expectEmit(true, true, false, true, address(router));
        emit PayRouter.OrderRejected(orderId, bob, ORDER_AMOUNT);
        router.rejectOrder(orderId);
    }

    function test_RejectOrder_NoFeeCharged() public {
        _setFeeBpsViaTimelock(100); // 1% fee active
        bytes32 orderId = _createOrderAsBob();
        uint256 bobBefore = usdc.balanceOf(bob);

        vm.prank(operator);
        router.rejectOrder(orderId);

        // Full amount returned, no fee deducted
        assertEq(usdc.balanceOf(bob), bobBefore + ORDER_AMOUNT);
    }

    function test_RevertRejectOrder_NotPending() public {
        bytes32 orderId = _createOrderAsBob();

        vm.prank(operator);
        router.rejectOrder(orderId);

        vm.prank(operator);
        vm.expectRevert(PayRouter.OrderNotPending.selector);
        router.rejectOrder(orderId);
    }

    // ─────────────────────────────────────────────────────────────
    // RECLAIM ORDER
    // ─────────────────────────────────────────────────────────────

    function test_RevertReclaimOrder_BeforeTimeout() public {
        bytes32 orderId = _createOrderAsBob();

        vm.prank(bob);
        vm.expectRevert(PayRouter.OrderNotExpired.selector);
        router.reclaimOrder(orderId);
    }

    function test_ReclaimOrder_AfterTimeout_Succeeds() public {
        bytes32 orderId = _createOrderAsBob();
        uint256 bobBefore = usdc.balanceOf(bob);

        vm.warp(block.timestamp + ORDER_TIMEOUT);

        vm.prank(bob);
        router.reclaimOrder(orderId);

        assertEq(usdc.balanceOf(bob), bobBefore + ORDER_AMOUNT);
        assertEq(uint8(_orderStatus(orderId)), uint8(PayRouter.OrderStatus.Reclaimed));
    }

    function test_ReclaimOrder_EmitsEvent() public {
        bytes32 orderId = _createOrderAsBob();

        vm.warp(block.timestamp + ORDER_TIMEOUT);

        vm.prank(bob);
        vm.expectEmit(true, true, false, true, address(router));
        emit PayRouter.OrderReclaimed(orderId, bob, ORDER_AMOUNT);
        router.reclaimOrder(orderId);
    }

    function test_RevertReclaimOrder_NotPending() public {
        bytes32 orderId = _createOrderAsBob();

        vm.prank(operator);
        router.fulfillOrder(orderId);

        vm.warp(block.timestamp + ORDER_TIMEOUT);

        vm.prank(bob);
        vm.expectRevert(PayRouter.OrderNotPending.selector);
        router.reclaimOrder(orderId);
    }

    // ─────────────────────────────────────────────────────────────
    // PAUSED — fulfill/reject/reclaim still work
    // ─────────────────────────────────────────────────────────────

    function test_Paused_FulfillOrderStillWorks() public {
        bytes32 orderId = _createOrderAsBob();

        vm.prank(admin);
        router.pause();

        // fulfill is not gated by whenNotPaused
        vm.prank(operator);
        router.fulfillOrder(orderId);

        assertEq(uint8(_orderStatus(orderId)), uint8(PayRouter.OrderStatus.Fulfilled));
    }

    function test_Paused_RejectOrderStillWorks() public {
        bytes32 orderId = _createOrderAsBob();

        vm.prank(admin);
        router.pause();

        vm.prank(operator);
        router.rejectOrder(orderId);

        assertEq(uint8(_orderStatus(orderId)), uint8(PayRouter.OrderStatus.Rejected));
    }

    function test_Paused_ReclaimOrderStillWorks() public {
        bytes32 orderId = _createOrderAsBob();

        vm.prank(admin);
        router.pause();

        vm.warp(block.timestamp + ORDER_TIMEOUT);

        vm.prank(bob);
        router.reclaimOrder(orderId);

        assertEq(uint8(_orderStatus(orderId)), uint8(PayRouter.OrderStatus.Reclaimed));
    }

    // ─────────────────────────────────────────────────────────────
    // WITNESS MISMATCH SECURITY TEST
    // ─────────────────────────────────────────────────────────────

    /// @dev Verifies that the witness passed to Permit2 encodes billerId, accountHash, ref.
    ///      If any of these differ at signing vs. submission, the computed witness changes
    ///      and real Permit2 would reject the signature.
    function test_WitnessMismatch_DifferentBillerIdChangesWitness() public {
        address biller2 = makeAddr("biller2");
        // Add biller2 via timelock
        _addBillerViaTimelock(biller2, makeAddr("biller2Treasury"));

        // Create two orders with different billerIds
        PermitTransferFrom memory permit1 = _buildWitnessPermit(ORDER_AMOUNT);
        vm.prank(bob);
        bytes32 orderId1 = router.createOrder(permit1, DUMMY_SIG, billerAddress, ACCOUNT_HASH, REF, ORDER_AMOUNT);

        // re-mint so bob has funds for second order
        usdc.mint(bob, ORDER_AMOUNT);

        PermitTransferFrom memory permit2 = _buildWitnessPermit(ORDER_AMOUNT);
        vm.prank(bob);
        bytes32 orderId2 = router.createOrder(permit2, DUMMY_SIG, biller2, ACCOUNT_HASH, REF, ORDER_AMOUNT);

        // Witness values must differ because billerIds differ
        bytes32 w1 = _expectedWitness(orderId1, billerAddress, ACCOUNT_HASH, REF);
        bytes32 w2 = _expectedWitness(orderId2, biller2,       ACCOUNT_HASH, REF);
        assertTrue(w1 != w2, "Witness must differ when billerId differs");
    }

    function test_WitnessMismatch_DifferentAccountHashChangesWitness() public {
        PermitTransferFrom memory permit = _buildWitnessPermit(ORDER_AMOUNT);
        vm.prank(bob);
        bytes32 orderId = router.createOrder(permit, DUMMY_SIG, billerAddress, ACCOUNT_HASH, REF, ORDER_AMOUNT);

        bytes32 differentAccountHash = keccak256("account-2");
        bytes32 w1 = _expectedWitness(orderId, billerAddress, ACCOUNT_HASH,         REF);
        bytes32 w2 = _expectedWitness(orderId, billerAddress, differentAccountHash, REF);
        assertTrue(w1 != w2, "Witness must differ when accountHash differs");
    }

    function test_WitnessMismatch_DifferentRefChangesWitness() public {
        PermitTransferFrom memory permit = _buildWitnessPermit(ORDER_AMOUNT);
        vm.prank(bob);
        bytes32 orderId = router.createOrder(permit, DUMMY_SIG, billerAddress, ACCOUNT_HASH, REF, ORDER_AMOUNT);

        bytes32 differentRef = keccak256("ref-2");
        bytes32 w1 = _expectedWitness(orderId, billerAddress, ACCOUNT_HASH, REF);
        bytes32 w2 = _expectedWitness(orderId, billerAddress, ACCOUNT_HASH, differentRef);
        assertTrue(w1 != w2, "Witness must differ when ref differs");
    }

    // ─────────────────────────────────────────────────────────────
    // CONCURRENT TWO-PAYER TEST
    // Proves per-payer nonces eliminate nonce interference between payers.
    // ─────────────────────────────────────────────────────────────

    /// @dev Two payers (bob and carol) each sign an orderId computed from their own nonce.
    ///      Both transactions succeed with no revert, proving nonce isolation.
    function test_ConcurrentTwoPayers_NoNonceInterference() public {
        // bob's nonce is 0, carol's nonce is also 0 — but they are independent mappings
        uint256 bobNonce   = router.orderNonceOf(bob);
        uint256 carolNonce = router.orderNonceOf(carol);
        assertEq(bobNonce,   0, "bob nonce should start at 0");
        assertEq(carolNonce, 0, "carol nonce should start at 0");

        // bob creates an order
        PermitTransferFrom memory permitBob = _buildWitnessPermit(ORDER_AMOUNT);
        vm.prank(bob);
        bytes32 orderIdBob = router.createOrder(permitBob, DUMMY_SIG, billerAddress, ACCOUNT_HASH, REF, ORDER_AMOUNT);

        // carol creates an order in the SAME block (same block.number, same block.timestamp)
        // with different biller ref so orderId is distinct even if nonces were equal
        bytes32 carolRef = keccak256("carol-ref");
        PermitTransferFrom memory permitCarol = _buildWitnessPermit(ORDER_AMOUNT);
        vm.prank(carol);
        bytes32 orderIdCarol = router.createOrder(permitCarol, DUMMY_SIG, billerAddress, ACCOUNT_HASH, carolRef, ORDER_AMOUNT);

        // Both orders are distinct and pending
        assertTrue(orderIdBob != orderIdCarol, "Order IDs must be distinct");
        (address payerBob,,,,, PayRouter.OrderStatus statusBob) = router.orders(orderIdBob);
        (address payerCarol,,,,, PayRouter.OrderStatus statusCarol) = router.orders(orderIdCarol);
        assertEq(payerBob,   bob);
        assertEq(payerCarol, carol);
        assertEq(uint8(statusBob),   uint8(PayRouter.OrderStatus.Pending));
        assertEq(uint8(statusCarol), uint8(PayRouter.OrderStatus.Pending));

        // bob's nonce advanced to 1; carol's nonce advanced to 1 independently
        assertEq(router.orderNonceOf(bob),   1, "bob nonce should be 1 after one order");
        assertEq(router.orderNonceOf(carol), 1, "carol nonce should be 1 after one order");
    }

    /// @dev Demonstrates orderId uniqueness: same payer, two sequential orders each get a distinct id.
    function test_SequentialOrders_SamePayer_UniqueIds() public {
        // First order
        PermitTransferFrom memory p1 = _buildWitnessPermit(ORDER_AMOUNT);
        vm.prank(bob);
        bytes32 id1 = router.createOrder(p1, DUMMY_SIG, billerAddress, ACCOUNT_HASH, REF, ORDER_AMOUNT);

        // Second order — nonce now 1
        usdc.mint(bob, ORDER_AMOUNT);
        bytes32 ref2 = keccak256("ref-2");
        PermitTransferFrom memory p2 = _buildWitnessPermit(ORDER_AMOUNT);
        vm.prank(bob);
        bytes32 id2 = router.createOrder(p2, DUMMY_SIG, billerAddress, ACCOUNT_HASH, ref2, ORDER_AMOUNT);

        assertTrue(id1 != id2, "Sequential orders from same payer must have distinct IDs");
        assertEq(router.orderNonceOf(bob), 2, "bob nonce should be 2 after two orders");
    }

    // ─────────────────────────────────────────────────────────────
    // INTERNAL HELPERS
    // ─────────────────────────────────────────────────────────────

    function _createOrderAsBob() internal returns (bytes32 orderId) {
        PermitTransferFrom memory permit = _buildWitnessPermit(ORDER_AMOUNT);
        vm.prank(bob);
        orderId = router.createOrder(permit, DUMMY_SIG, billerAddress, ACCOUNT_HASH, REF, ORDER_AMOUNT);
    }

    function _getOrder(bytes32 orderId) internal view returns (
        address payer, address treasury, uint128 amount,
        uint128 feeBps_, uint64 createdAt, PayRouter.OrderStatus status
    ) {
        (payer, treasury, amount, feeBps_, createdAt, status) = router.orders(orderId);
    }

    function _orderStatus(bytes32 orderId) internal view returns (PayRouter.OrderStatus) {
        (,,,,, PayRouter.OrderStatus s) = router.orders(orderId);
        return s;
    }

    /// Queue + warp + execute feeBps change via timelock.
    function _setFeeBpsViaTimelock(uint16 newBps) internal {
        bytes32 changeKey = keccak256("feeBps");
        bytes memory payload = abi.encode(newBps);

        vm.prank(admin);
        router.queueConfigChange(changeKey, payload);

        vm.warp(block.timestamp + 24 hours + 1);

        vm.prank(admin);
        router.executeConfigChange(changeKey);
    }

    function _addBillerViaTimelock(address biller, address treasury) internal {
        bytes32 changeKey = keccak256("addBiller");
        bytes memory payload = abi.encode(biller, treasury);

        vm.prank(admin);
        router.queueConfigChange(changeKey, payload);

        vm.warp(block.timestamp + 24 hours + 1);

        vm.prank(admin);
        router.executeConfigChange(changeKey);
    }
}

contracts/test/PayRouter.Send.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {PayRouterTestBase} from "./PayRouter.Base.t.sol";
import {PayRouter, PermitTransferFrom, SignatureTransferDetails} from "../PayRouter.sol";
import {MockPermit2} from "../test-helpers/MockPermit2.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

contract PayRouterSendTest is PayRouterTestBase {

    // ─────────────────────────────────────────────────────────────
    // SEND — happy path
    // ─────────────────────────────────────────────────────────────

    function test_Send_HappyPath_Tier0() public {
        uint256 amount = 5 * USDC_6; // exactly at Tier-0 per-payment cap

        vm.prank(alice);
        router.send(_buildPermit(amount), DUMMY_SIG, bob, amount);

        // Permit2 mock was called
        assertEq(permit2.permitCallCount(), 1);
        assertEq(permit2.lastOwner(), alice);
        assertEq(permit2.lastDetailsTo(), bob);
        assertEq(permit2.lastDetailsRequestedAmount(), amount);
    }

    function test_Send_HappyPath_EmitsSentEvent() public {
        uint256 amount = 5 * USDC_6;

        vm.prank(alice);
        vm.expectEmit(true, true, false, true, address(router));
        emit PayRouter.Sent(alice, bob, amount);
        router.send(_buildPermit(amount), DUMMY_SIG, bob, amount);
    }

    function test_Send_TransfersTokens() public {
        uint256 amount  = 5 * USDC_6;
        uint256 bobBefore = usdc.balanceOf(bob);

        vm.prank(alice);
        router.send(_buildPermit(amount), DUMMY_SIG, bob, amount);

        assertEq(usdc.balanceOf(bob), bobBefore + amount);
    }

    // ─────────────────────────────────────────────────────────────
    // SEND — tier limits
    // ─────────────────────────────────────────────────────────────

    function test_RevertSend_ExceedsTierPerPaymentCap_Tier0() public {
        uint256 amount = 6 * USDC_6; // > T0_PER_PAYMENT (5 USDC), <= GLOBAL_CAP (25 USDC)

        vm.prank(alice);
        vm.expectRevert(abi.encodeWithSelector(PayRouter.ExceedsTierPerPaymentCap.selector, uint8(0)));
        router.send(_buildPermit(amount), DUMMY_SIG, bob, amount);
    }

    function test_RevertSend_ExceedsGlobalCap() public {
        // bob is Tier-1 with per-payment cap 100 USDC, but globalCap is 25 USDC
        uint256 amount = 26 * USDC_6;

        vm.prank(bob);
        vm.expectRevert(PayRouter.ExceedsGlobalCap.selector);
        router.send(_buildPermit(amount), DUMMY_SIG, alice, amount);
    }

    function test_RevertSend_ExceedsTierDailyCap_Tier0() public {
        // T0 daily cap = 50 USDC. Send 5 USDC ten times (50 total).
        // The 11th (5 more) should revert.
        uint256 amount = 5 * USDC_6;

        for (uint256 i = 0; i < 10; i++) {
            vm.prank(alice);
            router.send(_buildPermit(amount), DUMMY_SIG, bob, amount);
        }

        // 11th send should revert
        vm.prank(alice);
        vm.expectRevert(abi.encodeWithSelector(PayRouter.ExceedsTierDailyCap.selector, uint8(0)));
        router.send(_buildPermit(amount), DUMMY_SIG, bob, amount);
    }

    function test_Send_DailyCapResets_AfterWarp() public {
        uint256 amount = 5 * USDC_6;

        vm.prank(alice);
        router.send(_buildPermit(amount), DUMMY_SIG, bob, amount);

        // warp forward exactly 1 day
        vm.warp(block.timestamp + 1 days);

        // re-seed alice (used tokens in first send)
        usdc.mint(alice, amount);

        vm.prank(alice);
        router.send(_buildPermit(amount), DUMMY_SIG, bob, amount);

        assertEq(permit2.permitCallCount(), 2);
    }

    // ─────────────────────────────────────────────────────────────
    // SEND — paused
    // ─────────────────────────────────────────────────────────────

    function test_RevertSend_WhenPaused() public {
        vm.prank(admin);
        router.pause();

        vm.prank(alice);
        vm.expectRevert(Pausable.EnforcedPause.selector);
        router.send(_buildPermit(5 * USDC_6), DUMMY_SIG, bob, 5 * USDC_6);
    }

    // ─────────────────────────────────────────────────────────────
    // SEND — invalid inputs
    // ─────────────────────────────────────────────────────────────

    function test_RevertSend_ZeroRecipient() public {
        vm.prank(alice);
        vm.expectRevert(PayRouter.ZeroAddress.selector);
        router.send(_buildPermit(5 * USDC_6), DUMMY_SIG, address(0), 5 * USDC_6);
    }

    function test_RevertSend_ZeroAmount() public {
        vm.prank(alice);
        vm.expectRevert(PayRouter.InvalidAmount.selector);
        router.send(_buildPermit(0), DUMMY_SIG, bob, 0);
    }

    function test_RevertSend_AmountMismatch() public {
        // permit says 5 USDC but send says 4 USDC
        PermitTransferFrom memory p = _buildPermit(5 * USDC_6);
        vm.prank(alice);
        vm.expectRevert(PayRouter.InvalidAmount.selector);
        router.send(p, DUMMY_SIG, bob, 4 * USDC_6);
    }

    // ─────────────────────────────────────────────────────────────
    // SENDTOHANDLE — happy path
    // ─────────────────────────────────────────────────────────────

    function test_SendToHandle_HappyPath() public {
        // Bob claims a handle
        vm.prank(bob);
        handleReg.claimHandle("bobhandle");

        uint256 amount = 5 * USDC_6;

        vm.prank(alice);
        vm.expectEmit(true, true, false, true, address(router));
        emit PayRouter.SentToHandle(alice, bob, "bobhandle", amount);
        router.sendToHandle(_buildPermit(amount), DUMMY_SIG, "bobhandle", amount);

        // Permit2 was called with recipient = bob
        assertEq(permit2.lastDetailsTo(), bob);
    }

    function test_RevertSendToHandle_HandleNotFound() public {
        uint256 amount = 5 * USDC_6;

        vm.prank(alice);
        vm.expectRevert(abi.encodeWithSelector(PayRouter.HandleNotFound.selector, "nobody"));
        router.sendToHandle(_buildPermit(amount), DUMMY_SIG, "nobody", amount);
    }

    function test_RevertSendToHandle_WhenPaused() public {
        vm.prank(bob);
        handleReg.claimHandle("bobhandle2");

        vm.prank(admin);
        router.pause();

        vm.prank(alice);
        vm.expectRevert(Pausable.EnforcedPause.selector);
        router.sendToHandle(_buildPermit(5 * USDC_6), DUMMY_SIG, "bobhandle2", 5 * USDC_6);
    }

    // ─────────────────────────────────────────────────────────────
    // REQUESTPAY — happy path
    // ─────────────────────────────────────────────────────────────

    function test_RequestPay_HappyPath_EmitsEvent() public {
        uint256 amount    = 5 * USDC_6;
        bytes32 requestId = keccak256("req-001");

        vm.prank(alice);
        vm.expectEmit(true, true, true, true, address(router));
        emit PayRouter.RequestPaid(alice, bob, requestId, amount);
        router.requestPay(_buildPermit(amount), DUMMY_SIG, requestId, bob, amount);
    }

    function test_RequestPay_TransfersTokens() public {
        uint256 amount    = 5 * USDC_6;
        bytes32 requestId = keccak256("req-002");
        uint256 bobBefore = usdc.balanceOf(bob);

        vm.prank(alice);
        router.requestPay(_buildPermit(amount), DUMMY_SIG, requestId, bob, amount);

        assertEq(usdc.balanceOf(bob), bobBefore + amount);
    }

    function test_RevertRequestPay_WhenPaused() public {
        vm.prank(admin);
        router.pause();

        vm.prank(alice);
        vm.expectRevert(Pausable.EnforcedPause.selector);
        router.requestPay(_buildPermit(5 * USDC_6), DUMMY_SIG, bytes32(0), bob, 5 * USDC_6);
    }

    // ─────────────────────────────────────────────────────────────
    // PERMIT2 SECURITY — third-party relay
    // ─────────────────────────────────────────────────────────────

    /// @dev Security: Real Permit2 enforces that the signature was produced by `owner`.
    ///      A relay attacker cannot supply a different owner and re-use a stolen signature.
    ///      We model this with a strict MockPermit2 (enforceSenderCheck=true) deployed
    ///      locally in this test, verifying that owner != msg.sender causes a revert.
    ///      The router always passes msg.sender as owner, so the only way to trigger a
    ///      victim's transfer is to control their private key (i.e., steal the sig).
    function test_Permit2_ThirdPartyRelayReverts() public {
        // Deploy a strict MockPermit2 that enforces owner == msg.sender
        MockPermit2 strictPermit2 = new MockPermit2(true);

        uint256 amount   = 5 * USDC_6;
        address attacker = makeAddr("attacker");

        PermitTransferFrom memory permit = _buildPermit(amount);

        // Attacker (msg.sender) tries to specify alice as the owner — mock rejects this.
        vm.prank(attacker);
        vm.expectRevert("MockPermit2: owner != msg.sender");
        strictPermit2.permitTransferFrom(
            permit,
            SignatureTransferDetails({to: attacker, requestedAmount: amount}),
            alice, // owner != msg.sender (attacker) → revert
            DUMMY_SIG
        );
    }
}

