// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {PayRouterTestBase} from "./PayRouter.Base.t.sol";
import {PayRouter} from "../PayRouter.sol";
import {IAccessControl} from "@openzeppelin/contracts/access/IAccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

contract PayRouterTimelockTest is PayRouterTestBase {

    bytes32 internal constant CHANGE_FEE_BPS = keccak256("feeBps");

    // ─────────────────────────────────────────────────────────────
    // TIMELOCK — queue + execute
    // ─────────────────────────────────────────────────────────────

    function test_QueueConfigChange_EmitsEvent() public {
        bytes memory payload = abi.encode(uint16(50));

        vm.prank(admin);
        vm.expectEmit(true, false, false, false, address(router));
        emit PayRouter.ConfigChangeQueued(CHANGE_FEE_BPS, 0); // eta ignored in check
        router.queueConfigChange(CHANGE_FEE_BPS, payload);
    }

    function test_RevertExecuteConfigChange_BeforeDelay() public {
        bytes memory payload = abi.encode(uint16(50));

        vm.prank(admin);
        router.queueConfigChange(CHANGE_FEE_BPS, payload);

        // Try to execute immediately
        vm.prank(admin);
        vm.expectRevert(PayRouter.TimelockNotReady.selector);
        router.executeConfigChange(CHANGE_FEE_BPS);
    }

    function test_ExecuteConfigChange_AfterDelay_UpdatesFeeBps() public {
        uint16 newBps = 100;
        bytes memory payload = abi.encode(newBps);

        vm.prank(admin);
        router.queueConfigChange(CHANGE_FEE_BPS, payload);

        vm.warp(block.timestamp + 24 hours + 1);

        vm.prank(admin);
        vm.expectEmit(true, false, false, false, address(router));
        emit PayRouter.ConfigChangeExecuted(CHANGE_FEE_BPS);
        router.executeConfigChange(CHANGE_FEE_BPS);

        assertEq(router.feeBps(), newBps);
    }

    function test_RevertExecuteConfigChange_AlreadyExecuted() public {
        bytes memory payload = abi.encode(uint16(50));

        vm.prank(admin);
        router.queueConfigChange(CHANGE_FEE_BPS, payload);

        vm.warp(block.timestamp + 24 hours + 1);

        vm.prank(admin);
        router.executeConfigChange(CHANGE_FEE_BPS);

        vm.prank(admin);
        vm.expectRevert(PayRouter.TimelockAlreadyExecuted.selector);
        router.executeConfigChange(CHANGE_FEE_BPS);
    }

    function test_RevertExecuteConfigChange_NotQueued() public {
        bytes32 unqueued = keccak256("feeBps"); // feeBps key but nothing queued

        vm.prank(admin);
        vm.expectRevert(PayRouter.TimelockNotQueued.selector);
        router.executeConfigChange(unqueued);
    }

    function test_TimelockCanChangeGlobalPerPaymentCap() public {
        bytes32 changeKey = keccak256("globalPerPaymentCap");
        uint96 newCap = 30_000_000;
        bytes memory payload = abi.encode(newCap);

        vm.prank(admin);
        router.queueConfigChange(changeKey, payload);

        vm.warp(block.timestamp + 24 hours + 1);

        vm.prank(admin);
        router.executeConfigChange(changeKey);

        assertEq(router.globalPerPaymentCap(), newCap);
    }

    function test_TimelockCanAddBiller() public {
        address newBiller   = makeAddr("newBiller");
        address newTreasury = makeAddr("newTreasury");

        bytes32 changeKey = keccak256("addBiller");
        bytes memory payload = abi.encode(newBiller, newTreasury);

        vm.prank(admin);
        router.queueConfigChange(changeKey, payload);

        vm.warp(block.timestamp + 24 hours + 1);

        vm.prank(admin);
        vm.expectEmit(true, true, false, false, address(router));
        emit PayRouter.BillerAdded(newBiller, newTreasury);
        router.executeConfigChange(changeKey);

        assertTrue(router.isBiller(newBiller));
        assertEq(router.billerTreasury(newBiller), newTreasury);
    }

    function test_TimelockCanRemoveBiller() public {
        bytes32 changeKey = keccak256("removeBiller");
        bytes memory payload = abi.encode(billerAddress);

        vm.prank(admin);
        router.queueConfigChange(changeKey, payload);

        vm.warp(block.timestamp + 24 hours + 1);

        vm.prank(admin);
        vm.expectEmit(true, false, false, false, address(router));
        emit PayRouter.BillerRemoved(billerAddress);
        router.executeConfigChange(changeKey);

        assertFalse(router.isBiller(billerAddress));
    }

    function test_RevertQueueConfigChange_UnsupportedKey() public {
        bytes32 badKey = keccak256("badKey");
        vm.prank(admin);
        vm.expectRevert(PayRouter.InvalidConfig.selector);
        router.queueConfigChange(badKey, abi.encode(uint256(1)));
    }

    function test_RevertQueueConfigChange_EmptyPayload() public {
        vm.prank(admin);
        vm.expectRevert(PayRouter.InvalidConfig.selector);
        router.queueConfigChange(CHANGE_FEE_BPS, new bytes(0));
    }

    function test_RevertQueueConfigChange_NonAdmin() public {
        bytes32 adminRole = router.DEFAULT_ADMIN_ROLE();
        vm.prank(alice);
        vm.expectRevert(
            abi.encodeWithSelector(
                IAccessControl.AccessControlUnauthorizedAccount.selector,
                alice,
                adminRole
            )
        );
        router.queueConfigChange(CHANGE_FEE_BPS, abi.encode(uint16(50)));
    }

    // ─────────────────────────────────────────────────────────────
    // PAUSE / UNPAUSE
    // ─────────────────────────────────────────────────────────────

    function test_PauserRole_CanPause() public {
        vm.prank(admin); // admin has PAUSER_ROLE from constructor
        router.pause();

        assertTrue(router.paused());
    }

    function test_PauserRole_CanUnpause() public {
        vm.prank(admin);
        router.pause();

        vm.prank(admin);
        router.unpause();

        assertFalse(router.paused());
    }

    function test_RevertPause_NonPauserRole() public {
        bytes32 pauserRole = router.PAUSER_ROLE();
        vm.prank(alice);
        vm.expectRevert(
            abi.encodeWithSelector(
                IAccessControl.AccessControlUnauthorizedAccount.selector,
                alice,
                pauserRole
            )
        );
        router.pause();
    }

    function test_RevertUnpause_NonPauserRole() public {
        vm.prank(admin);
        router.pause();

        bytes32 pauserRole = router.PAUSER_ROLE();
        vm.prank(alice);
        vm.expectRevert(
            abi.encodeWithSelector(
                IAccessControl.AccessControlUnauthorizedAccount.selector,
                alice,
                pauserRole
            )
        );
        router.unpause();
    }

    function test_GrantPauserRole_CanPause() public {
        address pauser = makeAddr("pauser");
        bytes32 pauserRole = router.PAUSER_ROLE();

        vm.prank(admin);
        router.grantRole(pauserRole, pauser);

        vm.prank(pauser);
        router.pause();

        assertTrue(router.paused());
    }
}

contracts/test/ScheduledPayouts.Base.t.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Test} from "forge-std/Test.sol";
import {MockERC20}   from "../test-helpers/MockERC20.sol";
import {MockPermit2} from "../test-helpers/MockPermit2.sol";
import {
    ScheduledPayouts,
    PermitTransferFrom,
    TokenPermissions
} from "../ScheduledPayouts.sol";

abstract contract ScheduledPayoutsTestBase is Test {

    // ── deployed contracts ────────────────────────────────────────
    MockERC20          internal usdc;
    MockPermit2        internal permit2;
    ScheduledPayouts   internal sp;

    // ── actors ────────────────────────────────────────────────────
    address internal admin = makeAddr("admin");
    address internal alice = makeAddr("alice");   // sender
    address internal bob   = makeAddr("bob");     // recipient
    address internal carol = makeAddr("carol");   // third party

    // ── constants ─────────────────────────────────────────────────
    uint256 internal constant USDC_6   = 1e6;          // 1 USDC
    uint128 internal constant SEED     = 10_000e6;     // 10 000 USDC

    bytes   internal constant DUMMY_SIG = hex"deadbeef";

    // ── ScheduleType enum values ──────────────────────────────────
    ScheduledPayouts.ScheduleType internal constant T_PAYLATER   = ScheduledPayouts.ScheduleType.PayLater;
    ScheduledPayouts.ScheduleType internal constant T_ALLOWANCE  = ScheduledPayouts.ScheduleType.Allowance;
    ScheduledPayouts.ScheduleType internal constant T_VESTING    = ScheduledPayouts.ScheduleType.Vesting;
    ScheduledPayouts.ScheduleType internal constant T_PAYROLL    = ScheduledPayouts.ScheduleType.Payroll;
    ScheduledPayouts.ScheduleType internal constant T_STREAMING  = ScheduledPayouts.ScheduleType.Streaming;

    // ─────────────────────────────────────────────────────────────
    // setUp — runs before every test
    // ─────────────────────────────────────────────────────────────
    function setUp() public virtual {
        // 1. Mock USDC (6 decimals)
        usdc = new MockERC20("Mock USDC", "mUSDC", 6);

        // 2. Mock Permit2 (enforceSenderCheck = false for normal flows)
        permit2 = new MockPermit2(false);

        // 3. ScheduledPayouts
        sp = new ScheduledPayouts(address(usdc), address(permit2), admin);

        // 4. Seed alice and approve Permit2
        usdc.mint(alice, SEED);
        vm.prank(alice);
        usdc.approve(address(permit2), type(uint256).max);
    }

    // ─────────────────────────────────────────────────────────────
    // scheduleId helper
    // ─────────────────────────────────────────────────────────────
    function _scheduleId(
        address sender,
        address recipient,
        uint256 nonce
    ) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(sender, recipient, nonce));
    }

    // ─────────────────────────────────────────────────────────────
    // PermitTransferFrom builder for deposit (canonical Permit2 — no witness field in struct)
    // The contract computes the witness hash and passes it as a separate bytes32 to Permit2.
    // ─────────────────────────────────────────────────────────────
    function _buildWitnessPermit(uint256 amount)
        internal
        view
        returns (PermitTransferFrom memory)
    {
        return PermitTransferFrom({
            permitted: TokenPermissions({token: address(usdc), amount: amount}),
            nonce:     0,
            deadline:  block.timestamp + 1 hours
        });
    }

    // ─────────────────────────────────────────────────────────────
    // ScheduleParams builders
    // ─────────────────────────────────────────────────────────────

    function _payLaterParams(
        address recipient,
        uint128 amount,
        uint64  endTime,
        bool    revocable
    ) internal pure returns (ScheduledPayouts.ScheduleParams memory) {
        return ScheduledPayouts.ScheduleParams({
            recipient:    recipient,
            scheduleType: ScheduledPayouts.ScheduleType.PayLater,
            revocable:    revocable,
            totalAmount:  amount,
            startTime:    0,
            endTime:      endTime,
            cliffEnd:     0,
            period:       0,
            periodAmount: 0
        });
    }

    function _allowanceParams(
        address recipient,
        uint128 total,
        uint128 perPeriod,
        uint64  period,
        bool    revocable
    ) internal view returns (ScheduledPayouts.ScheduleParams memory) {
        return ScheduledPayouts.ScheduleParams({
            recipient:    recipient,
            scheduleType: ScheduledPayouts.ScheduleType.Allowance,
            revocable:    revocable,
            totalAmount:  total,
            startTime:    uint64(block.timestamp),
            endTime:      uint64(block.timestamp) + uint64(total / perPeriod) * period + period,
            cliffEnd:     0,
            period:       period,
            periodAmount: perPeriod
        });
    }

    function _payrollParams(
        address recipient,
        uint128 total,
        uint128 perPeriod,
        uint64  period,
        bool    revocable
    ) internal view returns (ScheduledPayouts.ScheduleParams memory) {
        return ScheduledPayouts.ScheduleParams({
            recipient:    recipient,
            scheduleType: ScheduledPayouts.ScheduleType.Payroll,
            revocable:    revocable,
            totalAmount:  total,
            startTime:    uint64(block.timestamp),
            endTime:      uint64(block.timestamp) + uint64(total / perPeriod) * period + period,
            cliffEnd:     0,
            period:       period,
            periodAmount: perPeriod
        });
    }

    function _vestingParams(
        address recipient,
        uint128 amount,
        uint64  start,
        uint64  cliff,
        uint64  end_,
        bool    revocable
    ) internal pure returns (ScheduledPayouts.ScheduleParams memory) {
        return ScheduledPayouts.ScheduleParams({
            recipient:    recipient,
            scheduleType: ScheduledPayouts.ScheduleType.Vesting,
            revocable:    revocable,
            totalAmount:  amount,
            startTime:    start,
            endTime:      end_,
            cliffEnd:     cliff,
            period:       0,
            periodAmount: 0
        });
    }

    function _streamingParams(
        address recipient,
        uint128 amount,
        uint64  start,
        uint64  end_,
        bool    revocable
    ) internal pure returns (ScheduledPayouts.ScheduleParams memory) {
        return ScheduledPayouts.ScheduleParams({
            recipient:    recipient,
            scheduleType: ScheduledPayouts.ScheduleType.Streaming,
            revocable:    revocable,
            totalAmount:  amount,
            startTime:    start,
            endTime:      end_,
            cliffEnd:     0,
            period:       0,
            periodAmount: 0
        });
    }

    // ─────────────────────────────────────────────────────────────
    // Convenience: deposit from alice and return the scheduleId
    // ─────────────────────────────────────────────────────────────
    function _depositAs(
        address sender,
        ScheduledPayouts.ScheduleParams memory params
    ) internal returns (bytes32 id) {
        PermitTransferFrom memory p = _buildWitnessPermit(params.totalAmount);
        vm.prank(sender);
        id = sp.deposit(p, DUMMY_SIG, params);
    }
}

contracts/test/ScheduledPayouts.Permit.t.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {ScheduledPayoutsTestBase} from "./ScheduledPayouts.Base.t.sol";
import {ScheduledPayouts, PermitTransferFrom, TokenPermissions}
    from "../ScheduledPayouts.sol";
import {MockPermit2} from "../test-helpers/MockPermit2.sol";
import {Pausable}    from "@openzeppelin/contracts/utils/Pausable.sol";

// ─────────────────────────────────────────────────────────────────────────────
// PERMIT2 SECURITY
// ─────────────────────────────────────────────────────────────────────────────
contract ScheduledPayoutsPermitSecurityTest is ScheduledPayoutsTestBase {

    // ── relay-attack test ─────────────────────────────────────────
    // Deploy a strict MockPermit2 (enforceSenderCheck=true) and a second
    // ScheduledPayouts instance that uses it. Carol calls deposit() but the
    // permit's owner is alice — strict Permit2 rejects owner != msg.sender.

    function test_Permit2_RelayAttack_Reverts() public {
        // 1. Strict Permit2
        MockPermit2 strictPermit2 = new MockPermit2(true);
        ScheduledPayouts sp2 = new ScheduledPayouts(address(usdc), address(strictPermit2), admin);

        // 2. Alice approves the strict Permit2
        vm.prank(alice);
        usdc.approve(address(strictPermit2), type(uint256).max);

        // 3. Build permit — owner is alice (signed by alice off-chain)
        uint128 amt  = 5e6;
        uint64  end_ = uint64(block.timestamp) + 3600;
        PermitTransferFrom memory p = _buildWitnessPermit(amt);
        ScheduledPayouts.ScheduleParams memory params = _payLaterParams(bob, amt, end_, false);

        // 4. Carol attempts to relay alice's permit → strict Permit2 rejects
        //    because owner (alice) != msg.sender (carol)
        vm.prank(carol);
        vm.expectRevert(bytes("MockPermit2: owner != msg.sender"));
        sp2.deposit(p, DUMMY_SIG, params);
    }

    // ── witness-mismatch observation test ─────────────────────────
    // The contract writes the witness into the permit before calling Permit2.
    // If the params passed to deposit() differ from what was signed, the witness
    // the contract computes will differ from the one the signer expected.
    // MockPermit2 (non-strict) records lastWitnessValue; we check that two
    // deposits with different params produce different witness values.
    // In production, real Permit2 rejects a mismatched witness via EIP-712 sig
    // verification — the contract cannot forge a valid sig for a wrong witness.

    function test_Permit2_DifferentParams_ProduceDifferentWitnesses() public {
        uint128 amt  = 5e6;
        uint64  end_ = uint64(block.timestamp) + 3600;

        // Deposit 1
        _depositAs(alice, _payLaterParams(bob, amt, end_, false));
        bytes32 witness1 = permit2.lastWitnessValue();

        // Deposit 2 with different endTime (simulates tampered param)
        uint64 end2 = end_ + 60;
        // Mint extra for alice's second deposit
        usdc.mint(alice, amt);
        _depositAs(alice, _payLaterParams(bob, amt, end2, false));
        bytes32 witness2 = permit2.lastWitnessValue();

        // Witnesses must differ — a tampered param changes the witness hash
        assertTrue(witness1 != witness2, "witness should differ for different params");
    }

    // ── witness is set by contract, not by caller ──────────────────
    // Caller passes witness=bytes32(0). Contract overwrites it before calling
    // Permit2. Verify the recorded witness is non-zero.

    function test_Permit2_WitnessOverwrittenByContract() public {
        uint128 amt  = 5e6;
        uint64  end_ = uint64(block.timestamp) + 3600;
        _depositAs(alice, _payLaterParams(bob, amt, end_, false));

        // The mock records what the contract actually sent
        assertTrue(permit2.lastWitnessValue() != bytes32(0),
            "contract must overwrite zero witness with real hash");
    }

    // ── canonical witnessTypeString is passed correctly ──────────────────────
    // Real Permit2 takes a string (the type definition) not a bytes32 hash.
    // Verify the contract passes the correct canonical type string with TokenPermissions suffix.

    function test_Permit2_WitnessTypeStringPassedCorrectly() public {
        uint128 amt  = 5e6;
        uint64  end_ = uint64(block.timestamp) + 3600;
        _depositAs(alice, _payLaterParams(bob, amt, end_, false));

        string memory expectedTypeString = "ScheduleWitness(bytes32 scheduleId,address recipient,uint8 scheduleType,bool revocable,uint64 startTime,uint64 endTime,uint64 cliffEnd,uint64 period,uint128 periodAmount,uint128 totalAmount) TokenPermissions(address token,uint256 amount)";
        assertEq(permit2.lastWitnessTypeString(), expectedTypeString);
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// PAUSE
// ─────────────────────────────────────────────────────────────────────────────
contract ScheduledPayoutsPauseTest is ScheduledPayoutsTestBase {

    uint128 constant AMT  = 5e6;
    uint64  constant HOUR = 3600;

    // ── pause / unpause access control ───────────────────────────

    function test_Pause_NonPauserCannotPause() public {
        vm.prank(alice);
        vm.expectRevert(); // AccessControl revert
        sp.pause();
    }

    function test_Pause_NonPauserCannotUnpause() public {
        vm.prank(admin);
        sp.pause();

        vm.prank(alice);
        vm.expectRevert();
        sp.unpause();
    }

    function test_Pause_PauserCanPause() public {
        vm.prank(admin);
        sp.pause();
        assertTrue(sp.paused());
    }

    function test_Pause_PauserCanUnpause() public {
        vm.prank(admin);
        sp.pause();
        vm.prank(admin);
        sp.unpause();
        assertFalse(sp.paused());
    }

    // ── deposit blocked when paused ───────────────────────────────

    function test_Pause_DepositRevertsWhenPaused() public {
        vm.prank(admin);
        sp.pause();

        PermitTransferFrom memory p = _buildWitnessPermit(AMT);
        ScheduledPayouts.ScheduleParams memory params = _payLaterParams(bob, AMT, uint64(block.timestamp) + HOUR, false);

        vm.prank(alice);
        vm.expectRevert(Pausable.EnforcedPause.selector);
        sp.deposit(p, DUMMY_SIG, params);
    }

    // ── claim and cancel work while paused ────────────────────────

    function test_Pause_ClaimWorksWhilePaused() public {
        // Create schedule while unpaused
        uint64 end_ = uint64(block.timestamp) + HOUR;
        bytes32 id  = _depositAs(alice, _payLaterParams(bob, AMT, end_, false));

        // Pause, warp, claim
        vm.prank(admin);
        sp.pause();

        vm.warp(end_);
        sp.claim(id);  // must NOT revert

        assertEq(usdc.balanceOf(bob), AMT);
    }

    function test_Pause_CancelWorksWhilePaused() public {
        // Create revocable schedule while unpaused
        uint64 start = uint64(block.timestamp);
        uint64 end_  = start + HOUR;
        bytes32 id   = _depositAs(alice, _streamingParams(bob, AMT, start, end_, true));

        // Pause then cancel
        vm.prank(admin);
        sp.pause();

        vm.warp(start);  // 0 streamed
        uint256 aliceBefore = usdc.balanceOf(alice);

        vm.prank(alice);
        sp.cancel(id);  // must NOT revert

        assertEq(usdc.balanceOf(alice), aliceBefore + AMT);
    }

    // ── deposit works after unpause ───────────────────────────────

    function test_Pause_DepositWorksAfterUnpause() public {
        vm.prank(admin);
        sp.pause();
        vm.prank(admin);
        sp.unpause();

        uint64 end_ = uint64(block.timestamp) + HOUR;
        // Should not revert
        bytes32 id = _depositAs(alice, _payLaterParams(bob, AMT, end_, false));
        (address sender,,,,,,,,,,,) = sp.schedules(id);
        assertEq(sender, alice);
    }
}

contracts/test/ScheduledPayouts.Streamin.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {ScheduledPayoutsTestBase} from "./ScheduledPayouts.Base.t.sol";
import {ScheduledPayouts, PermitTransferFrom}
    from "../ScheduledPayouts.sol";

// ─────────────────────────────────────────────────────────────────────────────
// STREAMING
// ─────────────────────────────────────────────────────────────────────────────
contract ScheduledPayoutsStreamingTest is ScheduledPayoutsTestBase {

    uint128 constant AMT    = 100e6;   // 100 USDC
    uint64  constant WINDOW = 1000;    // 1000-second window (easy 10% increments)

    function _setupStreaming()
        internal
        returns (bytes32 id, uint64 start, uint64 end_)
    {
        start = uint64(block.timestamp);
        end_  = start + WINDOW;
        id    = _depositAs(alice, _streamingParams(bob, AMT, start, end_, true));
    }

    function test_Streaming_AtStartTime_ClaimableIsZero() public {
        (bytes32 id, uint64 start,) = _setupStreaming();
        vm.warp(start);
        assertEq(sp.claimableNow(id), 0);
    }

    function test_Streaming_HalfwayThrough_ClaimableIsHalf() public {
        (bytes32 id, uint64 start,) = _setupStreaming();
        vm.warp(start + WINDOW / 2);
        uint128 claimable = sp.claimableNow(id);
        // Allow ±1 for integer truncation
        assertApproxEqAbs(claimable, AMT / 2, 1);
    }

    function test_Streaming_AtEndTime_ClaimableEqualsTotal() public {
        (bytes32 id,, uint64 end_) = _setupStreaming();
        vm.warp(end_);
        assertEq(sp.claimableNow(id), AMT);
    }

    function test_Streaming_AfterEnd_ClaimableStillEqualsTotal() public {
        (bytes32 id,, uint64 end_) = _setupStreaming();
        vm.warp(end_ + 500);
        assertEq(sp.claimableNow(id), AMT);
    }

    function test_Streaming_MultipleSmallClaims_TotalEqualsAmt() public {
        (bytes32 id, uint64 start,) = _setupStreaming();
        uint256 totalClaimed = 0;
        uint256 step = WINDOW / 10;  // 10 claims at 10% intervals

        for (uint256 i = 1; i <= 10; i++) {
            vm.warp(start + step * i);
            uint128 before = sp.claimableNow(id);
            if (before > 0) {
                sp.claim(id);
                totalClaimed += before;
            }
        }
        assertEq(totalClaimed, AMT);
        assertEq(usdc.balanceOf(bob), AMT);
    }

    function test_Streaming_StartGeEnd_Reverts() public {
        uint64 t = uint64(block.timestamp);
        PermitTransferFrom memory p = _buildWitnessPermit(AMT);
        // startTime == endTime is invalid
        ScheduledPayouts.ScheduleParams memory params = _streamingParams(bob, AMT, t + 100, t + 100, false);
        vm.prank(alice);
        vm.expectRevert(ScheduledPayouts.InvalidScheduleParams.selector);
        sp.deposit(p, DUMMY_SIG, params);
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// PAYROLL (same unlock math as Allowance, different ScheduleType enum)
// ─────────────────────────────────────────────────────────────────────────────
contract ScheduledPayoutsPayrollTest is ScheduledPayoutsTestBase {

    uint128 constant TOTAL      = 10e6;
    uint128 constant PER_PERIOD = 2e6;
    uint64  constant PERIOD     = 1 days;

    function test_Payroll_TypeStoredAsPayroll() public {
        bytes32 id = _depositAs(alice, _payrollParams(bob, TOTAL, PER_PERIOD, PERIOD, false));
        (,, ScheduledPayouts.ScheduleType stype,,,,,,,,,) = sp.schedules(id);
        assertEq(uint8(stype), 3); // enum value 3 = Payroll
    }

    function test_Payroll_UnlockMatchesAllowanceMath() public {
        uint64 start = uint64(block.timestamp);
        bytes32 id   = _depositAs(alice, _payrollParams(bob, TOTAL, PER_PERIOD, PERIOD, false));

        // After 3 periods: 3 * 2 = 6 USDC
        vm.warp(start + 3 * PERIOD);
        assertEq(sp.claimableNow(id), 3 * PER_PERIOD);
    }

    function test_Payroll_CappedAtTotal() public {
        uint64 start = uint64(block.timestamp);
        bytes32 id   = _depositAs(alice, _payrollParams(bob, TOTAL, PER_PERIOD, PERIOD, false));

        vm.warp(start + 10 * PERIOD); // way beyond full vest
        assertEq(sp.claimableNow(id), TOTAL);
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// CANCEL
// ─────────────────────────────────────────────────────────────────────────────
contract ScheduledPayoutsCancelTest is ScheduledPayoutsTestBase {

    uint128 constant AMT    = 100e6;  // 100 USDC
    uint64  constant WINDOW = 1000;

    // Create a revocable streaming schedule and return (id, start, end)
    function _revocableStream()
        internal
        returns (bytes32 id, uint64 start, uint64 end_)
    {
        start = uint64(block.timestamp);
        end_  = start + WINDOW;
        id    = _depositAs(alice, _streamingParams(bob, AMT, start, end_, true));
    }

    // ── happy paths ──────────────────────────────────────────────

    function test_Cancel_BeforeAnyUnlock_RecipientGets0_SenderGetsAll() public {
        (bytes32 id, uint64 start,) = _revocableStream();
        vm.warp(start); // exactly at start, claimable == 0 for Streaming

        uint256 aliceBefore = usdc.balanceOf(alice);

        vm.prank(alice);
        sp.cancel(id);

        assertEq(usdc.balanceOf(bob),   0);       // recipient gets nothing
        assertEq(usdc.balanceOf(alice), aliceBefore + AMT);  // sender gets all back

        // schedule.cancelled = true
        (,,,, bool cancelled,,,,,,, ) = sp.schedules(id);
        assertTrue(cancelled);
    }

    function test_Cancel_At50Percent_RecipientGetsHalf_SenderGetsHalf() public {
        (bytes32 id, uint64 start,) = _revocableStream();
        vm.warp(start + WINDOW / 2);  // 50% streamed

        uint256 aliceBefore = usdc.balanceOf(alice);

        vm.prank(alice);
        sp.cancel(id);

        // Allow ±1 for integer truncation in the streaming formula
        assertApproxEqAbs(usdc.balanceOf(bob),   AMT / 2, 1);
        assertApproxEqAbs(usdc.balanceOf(alice),  aliceBefore + AMT / 2, 1);
    }

    function test_Cancel_AfterFullUnlock_RecipientGets100_SenderGets0() public {
        (bytes32 id,, uint64 end_) = _revocableStream();
        vm.warp(end_);  // 100% streamed but not yet claimed

        uint256 aliceBefore = usdc.balanceOf(alice);

        vm.prank(alice);
        sp.cancel(id);

        assertEq(usdc.balanceOf(bob),   AMT);            // recipient gets all
        assertEq(usdc.balanceOf(alice), aliceBefore);    // sender gets nothing
    }

    function test_Cancel_EmitsCancelled() public {
        (bytes32 id, uint64 start,) = _revocableStream();
        vm.warp(start);  // 0 unlocked

        vm.prank(alice);
        vm.expectEmit(true, true, true, true, address(sp));
        emit ScheduledPayouts.Cancelled(id, alice, bob, 0, AMT);
        sp.cancel(id);
    }

    function test_Cancel_ClaimableNow_ReturnsZeroAfterCancel() public {
        (bytes32 id, uint64 start,) = _revocableStream();
        vm.warp(start + WINDOW / 2);

        vm.prank(alice);
        sp.cancel(id);

        assertEq(sp.claimableNow(id), 0);
    }

    // ── revert paths ─────────────────────────────────────────────

    function test_Cancel_NonRevocable_RevertsNotRevocable() public {
        uint64 start = uint64(block.timestamp);
        uint64 end_  = start + WINDOW;
        bytes32 id   = _depositAs(alice, _streamingParams(bob, AMT, start, end_, false));

        vm.prank(alice);
        vm.expectRevert(ScheduledPayouts.NotRevocable.selector);
        sp.cancel(id);
    }

    function test_Cancel_NonRevocable_AdminAlsoReverts() public {
        uint64 start = uint64(block.timestamp);
        uint64 end_  = start + WINDOW;
        bytes32 id   = _depositAs(alice, _streamingParams(bob, AMT, start, end_, false));

        vm.prank(admin);
        vm.expectRevert(ScheduledPayouts.NotRevocable.selector);
        sp.cancel(id);
    }

    function test_Cancel_NonRevocable_CarolAlsoReverts() public {
        uint64 start = uint64(block.timestamp);
        uint64 end_  = start + WINDOW;
        bytes32 id   = _depositAs(alice, _streamingParams(bob, AMT, start, end_, false));

        vm.prank(carol);
        vm.expectRevert(ScheduledPayouts.NotRevocable.selector);
        sp.cancel(id);
    }

    function test_Cancel_NonSender_RevertsNotSender() public {
        (bytes32 id,,) = _revocableStream();

        vm.prank(bob);
        vm.expectRevert(ScheduledPayouts.NotSender.selector);
        sp.cancel(id);
    }

    function test_Cancel_DoubleCancel_RevertsScheduleCancelled() public {
        (bytes32 id, uint64 start,) = _revocableStream();
        vm.warp(start);

        vm.prank(alice);
        sp.cancel(id);

        vm.prank(alice);
        vm.expectRevert(ScheduledPayouts.ScheduleCancelled.selector);
        sp.cancel(id);
    }

    function test_Cancel_ClaimAfterCancel_RevertsScheduleCancelled() public {
        (bytes32 id,, uint64 end_) = _revocableStream();
        vm.warp(end_);  // fully unlocked

        vm.prank(alice);
        sp.cancel(id);

        vm.expectRevert(ScheduledPayouts.ScheduleCancelled.selector);
        sp.claim(id);
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// CLAIM
// ─────────────────────────────────────────────────────────────────────────────
contract ScheduledPayoutsClaimTest is ScheduledPayoutsTestBase {

    uint128 constant AMT  = 50e6;
    uint64  constant HOUR = 3600;

    // ── happy paths ──────────────────────────────────────────────

    function test_Claim_AnyoneCanCallClaim_BobGetsTokens() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        bytes32 id  = _depositAs(alice, _payLaterParams(bob, AMT, end_, false));
        vm.warp(end_);

        vm.prank(carol);  // carol triggers claim
        sp.claim(id);

        assertEq(usdc.balanceOf(bob),   AMT);  // bob received
        assertEq(usdc.balanceOf(carol), 0);    // carol got nothing
    }

    function test_Claim_SameBlock_SecondClaimRevertsNothingToClaim() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        bytes32 id  = _depositAs(alice, _payLaterParams(bob, AMT, end_, false));
        vm.warp(end_);

        sp.claim(id);

        vm.expectRevert(ScheduledPayouts.NothingToClaim.selector);
        sp.claim(id);
    }

    function test_Claim_DoubleClaimAfterWarp_EachTakesHalf() public {
        // Use streaming so we can claim at two different checkpoints
        uint64 start = uint64(block.timestamp);
        uint64 end_  = start + 1000;
        bytes32 id   = _depositAs(alice, _streamingParams(bob, AMT, start, end_, false));

        // First half
        vm.warp(start + 500);
        sp.claim(id);
        uint256 firstClaim = usdc.balanceOf(bob);

        // Second half
        vm.warp(end_);
        sp.claim(id);
        uint256 secondClaim = usdc.balanceOf(bob) - firstClaim;

        // Each ~half; allow ±1 for truncation
        assertApproxEqAbs(firstClaim,  AMT / 2, 1);
        assertApproxEqAbs(secondClaim, AMT / 2, 1);
        assertEq(usdc.balanceOf(bob),  AMT);
    }

    // ── revert paths ─────────────────────────────────────────────

    function test_Claim_UnknownSchedule_RevertsScheduleNotFound() public {
        vm.expectRevert(ScheduledPayouts.ScheduleNotFound.selector);
        sp.claim(bytes32(uint256(0xdead)));
    }
}

contracts/test/ScheduledPayouts.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {ScheduledPayoutsTestBase} from "./ScheduledPayouts.Base.t.sol";
import {ScheduledPayouts, PermitTransferFrom, TokenPermissions}
    from "../ScheduledPayouts.sol";
import {Pausable}    from "@openzeppelin/contracts/utils/Pausable.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";

// ─────────────────────────────────────────────────────────────────────────────
// DEPLOY & INITIALIZATION
// ─────────────────────────────────────────────────────────────────────────────
contract ScheduledPayoutsDeployTest is ScheduledPayoutsTestBase {

    function test_Deploy_SetsUsdcAndPermit2() public view {
        assertEq(address(sp.usdc()),   address(usdc));
        assertEq(address(sp.permit2()), address(permit2));
    }

    function test_Deploy_AdminHasDefaultAdminRole() public view {
        assertTrue(sp.hasRole(sp.DEFAULT_ADMIN_ROLE(), admin));
    }

    function test_Deploy_AdminHasPauserRole() public view {
        assertTrue(sp.hasRole(sp.PAUSER_ROLE(), admin));
    }

    function test_Deploy_ZeroUsdc_Reverts() public {
        vm.expectRevert(ScheduledPayouts.ZeroAddress.selector);
        new ScheduledPayouts(address(0), address(permit2), admin);
    }

    function test_Deploy_ZeroPermit2_Reverts() public {
        vm.expectRevert(ScheduledPayouts.ZeroAddress.selector);
        new ScheduledPayouts(address(usdc), address(0), admin);
    }

    function test_Deploy_ZeroAdmin_Reverts() public {
        vm.expectRevert(ScheduledPayouts.ZeroAddress.selector);
        new ScheduledPayouts(address(usdc), address(permit2), address(0));
    }

    function test_Deploy_InitialNonce_IsZero() public view {
        assertEq(sp.nextDepositNonce(alice), 0);
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// PAY LATER
// ─────────────────────────────────────────────────────────────────────────────
contract ScheduledPayoutsPayLaterTest is ScheduledPayoutsTestBase {

    uint128 constant AMT  = 5e6;    // 5 USDC
    uint64  constant HOUR = 3600;

    // ── happy path ───────────────────────────────────────────────

    function test_PayLater_HappyPath_ScheduleIdDerivation() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        bytes32 expected = _scheduleId(alice, bob, 0);
        bytes32 id = _depositAs(alice, _payLaterParams(bob, AMT, end_, true));
        assertEq(id, expected);
    }

    function test_PayLater_HappyPath_ScheduleStoredCorrectly() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        bytes32 id  = _depositAs(alice, _payLaterParams(bob, AMT, end_, true));

        (
            address sender,
            address recipient,
            ScheduledPayouts.ScheduleType stype,
            bool revocable,
            bool cancelled,
            uint128 totalAmount,
            uint128 claimed,
            ,
            uint64 endTime,
            ,
            ,

        ) = sp.schedules(id);

        assertEq(sender,      alice);
        assertEq(recipient,   bob);
        assertEq(uint8(stype), uint8(T_PAYLATER));
        assertTrue(revocable);
        assertFalse(cancelled);
        assertEq(totalAmount, AMT);
        assertEq(claimed,     0);
        assertEq(endTime,     end_);
    }

    function test_PayLater_HappyPath_EmitsScheduleCreated() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        bytes32 expected = _scheduleId(alice, bob, 0);

        PermitTransferFrom memory p = _buildWitnessPermit(AMT);
        ScheduledPayouts.ScheduleParams memory params = _payLaterParams(bob, AMT, end_, true);

        vm.prank(alice);
        vm.expectEmit(true, true, true, true, address(sp));
        emit ScheduledPayouts.ScheduleCreated(expected, alice, bob, T_PAYLATER, AMT);
        sp.deposit(p, DUMMY_SIG, params);
    }

    function test_PayLater_HappyPath_UsdcTransferredIn() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        _depositAs(alice, _payLaterParams(bob, AMT, end_, true));
        assertEq(usdc.balanceOf(address(sp)), AMT);
        assertEq(usdc.balanceOf(alice),       SEED - AMT);
    }

    function test_PayLater_BeforeEndTime_ClaimableIsZero() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        bytes32 id  = _depositAs(alice, _payLaterParams(bob, AMT, end_, true));

        vm.warp(block.timestamp + HOUR - 1);
        assertEq(sp.claimableNow(id), 0);
    }

    function test_PayLater_AtEndTime_ClaimableEqualsTotal() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        bytes32 id  = _depositAs(alice, _payLaterParams(bob, AMT, end_, true));

        vm.warp(end_);
        assertEq(sp.claimableNow(id), AMT);
    }

    function test_PayLater_HappyPath_ClaimAfterEnd_BobReceives() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        bytes32 id  = _depositAs(alice, _payLaterParams(bob, AMT, end_, true));

        vm.warp(end_);
        carol.call(""); // silence unused var warning — just verify bob balance
        uint256 bobBefore = usdc.balanceOf(bob);

        vm.prank(carol);  // anyone can call claim
        sp.claim(id);

        assertEq(usdc.balanceOf(bob),       bobBefore + AMT);
        assertEq(usdc.balanceOf(carol),     0);          // carol gets nothing
        assertEq(usdc.balanceOf(address(sp)), 0);
    }

    function test_PayLater_HappyPath_EmitsClaimed() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        bytes32 id  = _depositAs(alice, _payLaterParams(bob, AMT, end_, true));

        vm.warp(end_);
        vm.expectEmit(true, true, false, true, address(sp));
        emit ScheduledPayouts.Claimed(id, bob, AMT, AMT);
        sp.claim(id);
    }

    function test_PayLater_ClaimBeforeEnd_RevertsNothingToClaim() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        bytes32 id  = _depositAs(alice, _payLaterParams(bob, AMT, end_, true));

        vm.warp(end_ - 1);
        vm.expectRevert(ScheduledPayouts.NothingToClaim.selector);
        sp.claim(id);
    }

    function test_PayLater_NonceIncrements() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        _depositAs(alice, _payLaterParams(bob,   AMT, end_, true));  // nonce=0
        _depositAs(alice, _payLaterParams(carol, AMT, end_, true));  // nonce=1

        bytes32 id1 = _scheduleId(alice, bob,   0);
        bytes32 id2 = _scheduleId(alice, carol, 1);

        // both schedules exist (sender is non-zero)
        (address s1,,,,,,,,,,,) = sp.schedules(id1);
        (address s2,,,,,,,,,,,) = sp.schedules(id2);
        assertEq(s1, alice);
        assertEq(s2, alice);
        assertEq(sp.nextDepositNonce(alice), 2);
    }

    // ── revert paths ─────────────────────────────────────────────

    function test_PayLater_ZeroRecipient_Reverts() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        PermitTransferFrom memory p = _buildWitnessPermit(AMT);
        ScheduledPayouts.ScheduleParams memory params = _payLaterParams(address(0), AMT, end_, false);
        vm.prank(alice);
        vm.expectRevert(ScheduledPayouts.ZeroAddress.selector);
        sp.deposit(p, DUMMY_SIG, params);
    }

    function test_PayLater_ZeroAmount_Reverts() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        PermitTransferFrom memory p = _buildWitnessPermit(0);
        ScheduledPayouts.ScheduleParams memory params = _payLaterParams(bob, 0, end_, false);
        vm.prank(alice);
        vm.expectRevert(ScheduledPayouts.ZeroAmount.selector);
        sp.deposit(p, DUMMY_SIG, params);
    }

    function test_PayLater_EndTimeInPast_Reverts() public {
        uint64 end_ = uint64(block.timestamp) - 1;
        PermitTransferFrom memory p = _buildWitnessPermit(AMT);
        ScheduledPayouts.ScheduleParams memory params = _payLaterParams(bob, AMT, end_, false);
        vm.prank(alice);
        vm.expectRevert(ScheduledPayouts.InvalidScheduleParams.selector);
        sp.deposit(p, DUMMY_SIG, params);
    }

    function test_PayLater_AmountMismatch_Reverts() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        // permit says 10 USDC, params says 5
        PermitTransferFrom memory p = _buildWitnessPermit(10e6);
        ScheduledPayouts.ScheduleParams memory params = _payLaterParams(bob, AMT, end_, false);
        vm.prank(alice);
        vm.expectRevert(ScheduledPayouts.InvalidScheduleParams.selector);
        sp.deposit(p, DUMMY_SIG, params);
    }

    function test_PayLater_WrongToken_Reverts() public {
        uint64 end_ = uint64(block.timestamp) + HOUR;
        PermitTransferFrom memory p = PermitTransferFrom({
            permitted: TokenPermissions({token: address(0xdead), amount: AMT}),
            nonce:     0,
            deadline:  block.timestamp + 1 hours
        });
        ScheduledPayouts.ScheduleParams memory params = _payLaterParams(bob, AMT, end_, false);
        vm.prank(alice);
        vm.expectRevert(ScheduledPayouts.InvalidScheduleParams.selector);
        sp.deposit(p, DUMMY_SIG, params);
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// ALLOWANCE
// ─────────────────────────────────────────────────────────────────────────────
contract ScheduledPayoutsAllowanceTest is ScheduledPayoutsTestBase {

    uint128 constant TOTAL      = 10e6;   // 10 USDC total
    uint128 constant PER_PERIOD = 2e6;    //  2 USDC per period
    uint64  constant PERIOD     = 1 days;

    // Returns (id, startTime)
    function _setupAllowance() internal returns (bytes32 id, uint64 start) {
        start = uint64(block.timestamp);
        id    = _depositAs(alice, _allowanceParams(bob, TOTAL, PER_PERIOD, PERIOD, true));
    }

    function test_Allowance_HappyPath_ScheduleType() public {
        (bytes32 id,) = _setupAllowance();
        (,, ScheduledPayouts.ScheduleType stype,,,,,,,,,) = sp.schedules(id);
        assertEq(uint8(stype), uint8(T_ALLOWANCE));
    }

    function test_Allowance_After1Period_Claimable2USDC() public {
        (bytes32 id, uint64 start) = _setupAllowance();
        vm.warp(start + PERIOD);
        assertEq(sp.claimableNow(id), PER_PERIOD);
    }

    function test_Allowance_After5Periods_ClaimableCappedAtTotal() public {
        (bytes32 id, uint64 start) = _setupAllowance();
        vm.warp(start + 5 * PERIOD);
        assertEq(sp.claimableNow(id), TOTAL);
    }

    function test_Allowance_After6Periods_DoesNotExceedTotal() public {
        (bytes32 id, uint64 start) = _setupAllowance();
        vm.warp(start + 6 * PERIOD);
        assertEq(sp.claimableNow(id), TOTAL);
    }

    function test_Allowance_PartialClaimThenMore_OnlyNewPeriodUnlocked() public {
        (bytes32 id, uint64 start) = _setupAllowance();

        // Claim period 1 allocation
        vm.warp(start + PERIOD);
        assertEq(sp.claimableNow(id), PER_PERIOD);
        sp.claim(id);

        // After period 2 — only 1 new period worth should be claimable
        vm.warp(start + 2 * PERIOD);
        assertEq(sp.claimableNow(id), PER_PERIOD);

        sp.claim(id);
        assertEq(usdc.balanceOf(bob), PER_PERIOD * 2);
    }

    function test_Allowance_ZeroPeriod_Reverts() public {
        PermitTransferFrom memory p = _buildWitnessPermit(TOTAL);
        ScheduledPayouts.ScheduleParams memory params = ScheduledPayouts.ScheduleParams({
            recipient:    bob,
            scheduleType: T_ALLOWANCE,
            revocable:    false,
            totalAmount:  TOTAL,
            startTime:    uint64(block.timestamp),
            endTime:      uint64(block.timestamp) + 10 days,
            cliffEnd:     0,
            period:       0,   // <-- invalid
            periodAmount: PER_PERIOD
        });
        vm.prank(alice);
        vm.expectRevert(ScheduledPayouts.InvalidScheduleParams.selector);
        sp.deposit(p, DUMMY_SIG, params);
    }

    function test_Allowance_ZeroPeriodAmount_Reverts() public {
        PermitTransferFrom memory p = _buildWitnessPermit(TOTAL);
        ScheduledPayouts.ScheduleParams memory params = ScheduledPayouts.ScheduleParams({
            recipient:    bob,
            scheduleType: T_ALLOWANCE,
            revocable:    false,
            totalAmount:  TOTAL,
            startTime:    uint64(block.timestamp),
            endTime:      uint64(block.timestamp) + 10 days,
            cliffEnd:     0,
            period:       PERIOD,
            periodAmount: 0   // <-- invalid
        });
        vm.prank(alice);
        vm.expectRevert(ScheduledPayouts.InvalidScheduleParams.selector);
        sp.deposit(p, DUMMY_SIG, params);
    }

    function test_Allowance_PeriodAmountExceedsTotal_Reverts() public {
        PermitTransferFrom memory p = _buildWitnessPermit(TOTAL);
        ScheduledPayouts.ScheduleParams memory params = ScheduledPayouts.ScheduleParams({
            recipient:    bob,
            scheduleType: T_ALLOWANCE,
            revocable:    false,
            totalAmount:  TOTAL,
            startTime:    uint64(block.timestamp),
            endTime:      uint64(block.timestamp) + 10 days,
            cliffEnd:     0,
            period:       PERIOD,
            periodAmount: TOTAL + 1   // <-- exceeds total
        });
        vm.prank(alice);
        vm.expectRevert(ScheduledPayouts.InvalidScheduleParams.selector);
        sp.deposit(p, DUMMY_SIG, params);
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// VESTING
// ─────────────────────────────────────────────────────────────────────────────
contract ScheduledPayoutsVestingTest is ScheduledPayoutsTestBase {

    uint128 constant AMT    = 120e6;   // 120 USDC
    uint64  constant WINDOW = 120;     // 120-second vest window (easy math)

    // start=now, cliff=now+30s, end=now+120s
    function _setupVesting()
        internal
        returns (bytes32 id, uint64 start, uint64 cliff, uint64 end_)
    {
        start = uint64(block.timestamp);
        cliff = start + 30;
        end_  = start + WINDOW;
        id    = _depositAs(alice, _vestingParams(bob, AMT, start, cliff, end_, true));
    }

    function test_Vesting_BeforeCliff_ClaimableIsZero() public {
        (bytes32 id,, uint64 cliff,) = _setupVesting();
        vm.warp(cliff - 1);
        assertEq(sp.claimableNow(id), 0);
    }

    function test_Vesting_AtCliff_ClaimableIsPositive() public {
        (bytes32 id, uint64 start, uint64 cliff,) = _setupVesting();
        vm.warp(cliff);
        // linear from start: at cliff (t=30, window=120) => 30/120 * 120 = 30 USDC
        uint128 expected = uint128((uint256(AMT) * (cliff - start)) / WINDOW);
        assertEq(sp.claimableNow(id), expected);
    }

    function test_Vesting_AtEnd_ClaimableEqualsTotal() public {
        (bytes32 id,,, uint64 end_) = _setupVesting();
        vm.warp(end_);
        assertEq(sp.claimableNow(id), AMT);
    }

    function test_Vesting_AtEnd_ClaimAll() public {
        (bytes32 id,,, uint64 end_) = _setupVesting();
        vm.warp(end_);
        sp.claim(id);
        (,,,,, , uint128 claimed,,,,,) = sp.schedules(id);
        assertEq(claimed, AMT);
        assertEq(usdc.balanceOf(bob), AMT);
    }

    function test_Vesting_AfterEnd_ClaimableDoesNotExceedTotal() public {
        (bytes32 id,,, uint64 end_) = _setupVesting();
        vm.warp(end_ + 1000);
        assertEq(sp.claimableNow(id), AMT);
    }

    function test_Vesting_ImmediateCliff_AtStart_ClaimableIsZero() public {
        // cliffEnd == startTime; at exactly startTime the linear calc gives 0
        uint64 start = uint64(block.timestamp);
        uint64 cliff = start;          // immediate cliff
        uint64 end_  = start + WINDOW;
        bytes32 id = _depositAs(alice, _vestingParams(bob, AMT, start, cliff, end_, false));

        vm.warp(start);
        // t == startTime: (totalAmount * (t - startTime)) / window = 0
        assertEq(sp.claimableNow(id), 0);
    }

    function test_Vesting_StartGeEnd_Reverts() public {
        uint64 t = uint64(block.timestamp);
        PermitTransferFrom memory p = _buildWitnessPermit(AMT);
        ScheduledPayouts.ScheduleParams memory params = _vestingParams(bob, AMT, t + 10, t, t + 10, false); // start >= end
        vm.prank(alice);
        vm.expectRevert(ScheduledPayouts.InvalidScheduleParams.selector);
        sp.deposit(p, DUMMY_SIG, params);
    }

    function test_Vesting_CliffBeforeStart_Reverts() public {
        uint64 t = uint64(block.timestamp);
        PermitTransferFrom memory p = _buildWitnessPermit(AMT);
        // cliffEnd < startTime
        ScheduledPayouts.ScheduleParams memory params = _vestingParams(bob, AMT, t + 10, t + 5, t + 100, false);
        vm.prank(alice);
        vm.expectRevert(ScheduledPayouts.InvalidScheduleParams.selector);
        sp.deposit(p, DUMMY_SIG, params);
    }

    function test_Vesting_CliffAfterEnd_Reverts() public {
        uint64 t = uint64(block.timestamp);
        PermitTransferFrom memory p = _buildWitnessPermit(AMT);
        // cliffEnd > endTime
        ScheduledPayouts.ScheduleParams memory params = _vestingParams(bob, AMT, t, t + 200, t + 100, false);
        vm.prank(alice);
        vm.expectRevert(ScheduledPayouts.InvalidScheduleParams.selector);
        sp.deposit(p, DUMMY_SIG, params);
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// WITHDRAW (pendingWithdrawals)
// ─────────────────────────────────────────────────────────────────────────────
contract ScheduledPayoutsWithdrawTest is ScheduledPayoutsTestBase {

    function test_Withdraw_ZeroBalance_RevertsNothingToClaim() public {
        vm.prank(bob);
        vm.expectRevert(ScheduledPayouts.NothingToClaim.selector);
        sp.withdraw();
    }

    function test_Withdraw_NormalFlow_PendingIsZeroAfterClaim() public {
        // In normal flow (MockERC20 succeeds), _push succeeds, no pending balance
        uint64 end_ = uint64(block.timestamp) + 1;
        bytes32 id  = _depositAs(alice, _payLaterParams(bob, 5e6, end_, false));
        vm.warp(end_);
        sp.claim(id);
        // pendingWithdrawals should be 0 — direct transfer succeeded
        assertEq(sp.pendingWithdrawals(bob), 0);
        assertEq(usdc.balanceOf(bob), 5e6);
    }

    function test_Withdraw_EmitsWithdrawnEvent() public {
        // To test Withdrawn event we need a pendingWithdrawal.
        // We use vm.store to set it directly (no reverting mock needed).
        // pendingWithdrawals is at slot 2 in the mapping (slot = keccak256(key . 2))
        // We seed a pending balance via storage manipulation.
        uint128 amount = 7e6;
        usdc.mint(address(sp), amount);  // contract must hold the funds

        // Write pendingWithdrawals[bob] = amount  (pendingWithdrawals is at slot 3)
        bytes32 slot = keccak256(abi.encode(bob, uint256(3)));
        vm.store(address(sp), slot, bytes32(uint256(amount)));

        assertEq(sp.pendingWithdrawals(bob), amount);

        vm.prank(bob);
        vm.expectEmit(true, false, false, true, address(sp));
        emit ScheduledPayouts.Withdrawn(bob, amount);
        sp.withdraw();

        assertEq(usdc.balanceOf(bob),       amount);
        assertEq(sp.pendingWithdrawals(bob), 0);
    }

    // Note: full blocklist simulation (where _push fails and pendingWithdrawals
    // is populated via the claim/cancel path) requires a reverting USDC mock.
    // That is a post-deploy integration concern and is not covered in this hermetic
    // unit-test file.
}

